"use client";

import { useState } from "react";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import { kitFileUrl, kitZipUrl } from "@/lib/partner-kit-urls";
import type { KitAsset, KitGuide, PartnerKit } from "@/lib/partner-kits";

/* The "Your sponsored segment" + "Generic English version" blocks at the top of
   the partner portal's Media kit tab. Data comes from lib/partner-kits.ts
   (loaded server-side in app/dashboard/partner/page.tsx); every file is served
   by the authenticated route app/api/creator-partner/kits/[code]/[file]. */

export type PartnerKits = { personal: PartnerKit | null; generic: PartnerKit | null };

export function SponsoredSegmentBlocks({ kits, code }: { kits: PartnerKits; code: string }) {
  const { personal, generic } = kits;
  if (!personal && !generic) return null;
  return (
    <>
      {personal && (
        <Panel
          title="Your sponsored segment"
          sub={`Made for your channel, with your code ${code} on screen. ${langCount(personal)} · ${fmtSize(personal.totalBytes)}`}
          action={<ZipButton kit={personal} primary />}
        >
          <KitBody kit={personal} guideOpen />
        </Panel>
      )}
      {generic && (
        <Panel
          title="Generic English version"
          sub="No creator code on screen. Use it for any video, and say your own code where the guide does."
          action={<ZipButton kit={generic} primary={!personal} />}
        >
          {!personal && (
            <div role="status" className="flex items-start gap-2.5 rounded-[12px] border border-[rgba(95,208,255,0.3)] bg-[rgba(95,208,255,0.07)] px-3.5 py-2.5">
              <Icon name="sparkles" size={15} tone="cyan" className="mt-[1px] flex-none" />
              <span className="text-[12.5px] leading-relaxed text-tx-dim">
                Your personal version, with your code <b className="mono text-white">{code}</b> on screen, is on the
                way. It will appear here as soon as it&apos;s ready. Until then, use this one.
              </span>
            </div>
          )}
          <div className={!personal ? "mt-3" : ""}>
            <KitBody kit={generic} guideOpen={!personal} />
          </div>
        </Panel>
      )}
    </>
  );
}

function langCount(kit: PartnerKit): string {
  const n = kit.assets.length;
  return n === 1 ? `1 language (${kit.assets[0].langLabel})` : `${n} languages`;
}

function ZipButton({ kit, primary }: { kit: PartnerKit; primary?: boolean }) {
  return (
    <a
      href={kitZipUrl(kit.code)}
      download
      className={(primary ? "btn-primary" : "btn-secondary") + " hidden h-[38px] flex-none gap-2 px-3.5 text-[12.5px] sm:inline-flex"}
    >
      <Icon name="download" size={14} tone="inherit" /> Download everything
      <span className="font-semibold opacity-75">({fmtSize(kit.totalBytes)} .zip)</span>
    </a>
  );
}

function KitBody({ kit, guideOpen }: { kit: PartnerKit; guideOpen: boolean }) {
  const g = kit.guide;
  const odd = kit.assets.length % 2 === 1;
  return (
    <div className="flex min-w-0 flex-col gap-3">
      {/* The header action is hidden at phone width — the full-width button lives here instead. */}
      <a href={kitZipUrl(kit.code)} download className="btn-secondary h-[40px] gap-2 px-3.5 text-[12.5px] sm:hidden">
        <Icon name="download" size={14} tone="inherit" /> Download everything ({fmtSize(kit.totalBytes)} .zip)
      </a>

      <div className="grid min-w-0 gap-3 md:grid-cols-2">
        {kit.assets.map((a) => (
          <VideoCard key={a.video.name} code={kit.code} asset={a} />
        ))}
        {odd && <AboutCard guide={g} kit={kit} />}
      </div>

      {g && (
        guideOpen ? (
          <GuideBlocks guide={g} kit={kit} showAbout={!odd} />
        ) : (
          <details className="group rounded-[12px] border border-rim-soft bg-well">
            <summary className="flex cursor-pointer list-none items-center gap-2 px-3.5 py-3 text-[12.5px] font-bold text-white [&::-webkit-details-marker]:hidden">
              <Icon name="file" size={14} className="flex-none" />
              How to use it, narration and description text
              <span className="ml-auto text-[11.5px] font-semibold text-cyan group-open:hidden">Show</span>
              <span className="ml-auto hidden text-[11.5px] font-semibold text-cyan group-open:inline">Hide</span>
            </summary>
            <div className="border-t border-rim-soft p-3">
              <GuideBlocks guide={g} kit={kit} showAbout={!odd} />
            </div>
          </details>
        )
      )}

      {kit.others.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 text-[12px]">
          <span className="text-tx-faint">Other files</span>
          {kit.others.map((f) => (
            <a key={f.name} href={kitFileUrl(kit.code, f.name, true)} className="mono truncate rounded-[8px] border border-rim-soft bg-well px-2.5 py-1 text-[11.5px] text-tx-dim hover:border-[#2f7eef] hover:text-white">
              {f.name} · {fmtSize(f.sizeBytes)}
            </a>
          ))}
        </div>
      )}
    </div>
  );
}

function VideoCard({ code, asset }: { code: string; asset: KitAsset }) {
  return (
    <div className="flex min-w-0 flex-col overflow-hidden rounded-[12px] border border-rim-soft bg-well">
      <div className="nx-dark-island relative aspect-video w-full bg-[#03060f]">
        <video
          controls
          preload="metadata"
          playsInline
          poster={asset.endframe ? kitFileUrl(code, asset.endframe.name) : undefined}
          className="absolute inset-0 h-full w-full bg-[#03060f] object-contain"
          aria-label={`Sponsored segment, ${asset.langLabel}`}
        >
          <source src={kitFileUrl(code, asset.video.name)} type="video/mp4" />
        </video>
      </div>
      <div className="flex flex-col gap-2.5 border-t border-rim-soft px-3.5 py-3">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-[13.5px] font-extrabold tracking-[-0.01em] text-white">{asset.langLabel}</span>
          {asset.aspect && <span className="chip-tone chip-blue">{asset.aspect}</span>}
          <span className="ml-auto text-[11px] text-tx-faint">{fmtSize(asset.video.sizeBytes)}</span>
        </div>
        <div className="flex flex-col gap-2 min-[440px]:flex-row min-[440px]:flex-wrap">
          <a href={kitFileUrl(code, asset.video.name, true)} className="btn-primary h-[36px] gap-2 whitespace-nowrap px-3 text-[12.5px] min-[440px]:flex-none">
            <Icon name="video" size={14} tone="inherit" /> Download video
          </a>
          {asset.endframe && (
            <a href={kitFileUrl(code, asset.endframe.name, true)} className="btn-secondary h-[36px] gap-2 whitespace-nowrap px-3 text-[12.5px] min-[440px]:flex-none">
              <Icon name="download" size={14} tone="inherit" /> Download end frame
            </a>
          )}
        </div>
      </div>
    </div>
  );
}

/** Fills the empty half of the grid when a kit has an odd number of videos. */
function AboutCard({ guide, kit }: { guide: KitGuide | null; kit: PartnerKit }) {
  return (
    <div className="flex min-w-0 flex-col gap-3 rounded-[12px] border border-rim-soft bg-well p-4">
      <SubHead icon="sparkles" title="What it is" />
      <p className="text-[12.5px] leading-relaxed text-tx-mute">
        {guide?.whatItIs ?? "A short sponsored segment showing the real Nxeon game-server flow, ready to drop into your edit."}
      </p>
      {guide?.filesNote && <p className="text-[12px] leading-relaxed text-tx-faint">{guide.filesNote}</p>}
      <FileList kit={kit} />
    </div>
  );
}

function FileList({ kit }: { kit: PartnerKit }) {
  const rows = kit.assets.flatMap((a) => [a.video, ...(a.endframe ? [a.endframe] : [])]);
  if (kit.guideFile) rows.push(kit.guideFile);
  return (
    <ul className="mt-auto flex flex-col gap-1.5 border-t border-rim-soft pt-3">
      {rows.map((f) => (
        <li key={f.name} className="flex min-w-0 items-center gap-2 text-[11.5px]">
          <Icon name={f.name.endsWith(".mp4") ? "video" : f.name.endsWith(".txt") ? "file" : "eye"} size={12} className="flex-none" />
          <a href={kitFileUrl(kit.code, f.name, true)} className="mono min-w-0 flex-1 truncate text-tx-dim hover:text-white">{f.name}</a>
          <span className="flex-none text-tx-faint">{fmtSize(f.sizeBytes)}</span>
        </li>
      ))}
    </ul>
  );
}

function SubHead({ icon, title, sub }: { icon: string; title: string; sub?: string | null }) {
  return (
    <span className="flex min-w-0 items-start gap-2">
      <Icon name={icon} size={14} className="mt-[2px] flex-none" />
      <span className="flex min-w-0 flex-col">
        <span className="text-[13px] font-extrabold tracking-[-0.01em] text-white">{title}</span>
        {sub && <span className="text-[11px] text-tx-faint">{sub}</span>}
      </span>
    </span>
  );
}

function GuideBlocks({ guide, kit, showAbout }: { guide: KitGuide; kit: PartnerKit; showAbout: boolean }) {
  return (
    <div className="flex min-w-0 flex-col gap-3">
      {showAbout && (guide.whatItIs || guide.filesNote) && (
        <div className="rounded-[12px] border border-rim-soft bg-well p-4">
          <SubHead icon="sparkles" title="What it is" />
          {guide.whatItIs && <p className="mt-2 text-[12.5px] leading-relaxed text-tx-mute">{guide.whatItIs}</p>}
          {guide.filesNote && <p className="mt-2 text-[12px] leading-relaxed text-tx-faint">{guide.filesNote}</p>}
        </div>
      )}

      {/* Left: the steps, then the description they point to; right: the narration. */}
      <div className="grid min-w-0 items-start gap-3 lg:grid-cols-2">
        <div className="flex min-w-0 flex-col gap-3">
          {guide.steps.length > 0 && (
            <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
              <SubHead icon="checkcircle" title="How to use it" />
              <ol className="mt-3 flex flex-col gap-2.5">
                {guide.steps.map((s, i) => (
                  <li key={i} className="flex items-start gap-2.5">
                    <span className="grid h-[22px] w-[22px] flex-none place-items-center rounded-full border border-[#8b5cff]/60 bg-[rgba(139,92,255,0.14)] text-[11px] font-extrabold text-white">
                      {i + 1}
                    </span>
                    <span className="min-w-0 text-[12.5px] leading-relaxed text-tx-mute">{s}</span>
                  </li>
                ))}
              </ol>
            </div>
          )}
          {guide.description && <DescriptionBox text={guide.description} />}
        </div>
        {guide.narration.length > 0 && (
          <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
            <SubHead icon="mic" title="Suggested narration" sub={guide.narrationNote ? cap(guide.narrationNote) : null} />
            <ol className="mt-3 flex flex-col">
              {guide.narration.map((n, i) => (
                <li key={i} className="flex items-start gap-3 border-t border-rim-soft py-2 first:border-t-0 first:pt-0 last:pb-0">
                  <span className="mono w-[42px] flex-none rounded-[6px] border border-rim-hi bg-[rgba(95,208,255,0.08)] py-[2px] text-center text-[11px] font-bold text-cyan">
                    {n.at}
                  </span>
                  <span className="min-w-0 text-[12.5px] leading-relaxed text-tx-mute">{n.text}</span>
                </li>
              ))}
            </ol>
          </div>
        )}
      </div>

      {guide.extra.map((e) => (
        <div key={e.heading} className="rounded-[12px] border border-rim-soft bg-well p-4">
          <SubHead icon="file" title={e.heading} />
          <p className="mt-2 whitespace-pre-line text-[12.5px] leading-relaxed text-tx-mute">{e.body}</p>
        </div>
      ))}

      <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-[11.5px] text-tx-faint">
        {guide.contact && (
          <span className="flex min-w-0 items-center gap-1.5">
            <Icon name="envelope" size={12} className="flex-none" />
            Questions?{" "}
            {/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(guide.contact) ? (
              <a href={`mailto:${guide.contact}`} className="font-semibold text-cyan hover:text-white">{guide.contact}</a>
            ) : (
              <span className="text-tx-dim">{guide.contact}</span>
            )}
          </span>
        )}
        {kit.guideFile && (
          <a href={kitFileUrl(kit.code, kit.guideFile.name, true)} className="flex items-center gap-1.5 font-semibold text-cyan hover:text-white sm:ml-auto">
            <Icon name="download" size={12} tone="inherit" /> Download this guide (.txt)
          </a>
        )}
      </div>
    </div>
  );
}

function DescriptionBox({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch { /* clipboard blocked — the text is still selectable */ }
  };
  return (
    <div className="min-w-0 rounded-[12px] border border-rim-soft bg-well p-4">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <SubHead icon="copy" title="Description text" sub="Paste it into your video description, with the paid-promotion box ticked." />
        <button type="button" onClick={copy} className="btn-primary h-[34px] flex-none gap-1.5 px-3.5 text-[12.5px]">
          <Icon name={copied ? "check" : "copy"} size={13} tone="inherit" /> {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <p className="mt-3 whitespace-pre-line break-words rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.5)] px-3.5 py-3 text-[12.5px] leading-relaxed text-white select-all">
        {text}
      </p>
    </div>
  );
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function fmtSize(n: number): string {
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
  return `${n} B`;
}
// Who may fetch a creator media-kit file (lib/partner-kits.ts). Same model as
// app/api/creator-partner/[doc]/route.ts — the signed-in user, 401 when signed
// out, 404 (never 403) when they may not see it so the URL space isn't
// advertised — narrowed per kit:
//   - a partner: their OWN code's folder + the generic one, nothing else;
//   - billing-area staff (ADMIN, BILLING — the same gate as /admin/partners/<id>,
//     where the owner previews a creator's kit): any folder.
// `currentUser()` follows impersonation, so an admin impersonating a partner
// sees exactly that partner's files; the staff check reads the REAL account.

import { currentUser, realUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { canAccess, isStaff } from "@/lib/rbac";
import { GENERIC_KIT, isKitCode } from "@/lib/partner-kits";

export type KitAccess = { ok: true } | { ok: false; status: 401 | 404 };

export async function kitAccess(code: string): Promise<KitAccess> {
  if (!isKitCode(code)) return { ok: false, status: 404 };
  const user = await currentUser();
  if (!user) return { ok: false, status: 401 };
  const real = await realUser();
  if (real && isStaff(real.role) && canAccess(real.role, "billing")) return { ok: true };
  const partner = await db.referralPartner.findUnique({ where: { userId: user.id }, select: { code: true } });
  if (!partner) return { ok: false, status: 404 };
  if (code === GENERIC_KIT) return { ok: true };
  return partner.code.trim().toUpperCase() === code ? { ok: true } : { ok: false, status: 404 };
}
// URLs of creator media-kit files (lib/partner-kits.ts). Plain module, no
// node: imports, so the client UI (components/nx/PartnerMediaKit.tsx) can use it.

/** One kit file — inline (preview/player), or an attachment with `download`. */
export function kitFileUrl(code: string, name: string, download = false): string {
  return `/api/creator-partner/kits/${encodeURIComponent(code)}/${encodeURIComponent(name)}${download ? "?download=1" : ""}`;
}

/** A whole kit as one zip. */
export function kitZipUrl(code: string): string {
  return `/api/creator-partner/kits/${encodeURIComponent(code)}`;
}

// Creator Partner Program — per-creator MEDIA KITS (sponsored-segment videos).
//
// The owner cuts a sponsored segment for a creator (sometimes in several
// languages), with an end-frame still and a HOW-TO-USE.txt. Each partner sees
// their OWN kit plus a generic English cut for everyone, on the "Media kit" tab
// of /dashboard/partner. Files are served by the authenticated, Range-capable
// route app/api/creator-partner/kits/[code]/[file]/route.ts (zip of a whole
// kit: app/api/creator-partner/kits/[code]/route.ts).
//
// Layout — under the same out-of-repo dir as the partner PDFs
// (lib/partner-files.ts, `NXEON_PARTNER_FILES_DIR`), so publishing is a file
// copy, never a deploy:
//
//   <PARTNER_FILES_DIR>/kits/<CODE>/      one folder per ReferralPartner.code (UPPERCASE)
//   <PARTNER_FILES_DIR>/kits/_generic/    shown to every partner
//
//   nxeon-promo_<CODE>_<lang>_16x9.mp4            the video, one per language
//   nxeon-promo_<CODE>_<lang>_16x9_endframe.png   its end frame (optional; poster + download)
//   HOW-TO-USE.txt                                the guide, parsed into UI by parseKitGuide()
//
// SECURITY: the URL can only ever name a file that is IN the directory
// listing (an exact-match whitelist), the code is validated against a strict
// pattern before it touches a path, and nothing but regular files with a known
// extension is listed (symlinks and subdirectories are skipped). See
// resolveKitFile().

import { promises as fs } from "node:fs";
import { join } from "node:path";
import { PARTNER_FILES_DIR } from "./partner-files";

export const KITS_DIR = join(PARTNER_FILES_DIR, "kits");
export const GENERIC_KIT = "_generic";
export const GUIDE_FILE = "HOW-TO-USE.txt";

const CODE_RE = /^[A-Z0-9-]{2,20}$/;
/** A plain file name: no separators, no leading dot, no "..". */
const NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$/;

export const KIT_CONTENT_TYPES: Record<string, string> = {
  mp4: "video/mp4",
  webm: "video/webm",
  mov: "video/quicktime",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  txt: "text/plain; charset=utf-8",
  pdf: "application/pdf",
};

/** Display names for the language tags in the file names. */
export const KIT_LANGUAGES: Record<string, string> = {
  en: "English",
  tr: "Turkish",
  tl: "Filipino (Tagalog)",
  es: "Spanish",
  hi: "Hindi",
  pt: "Portuguese",
  de: "German",
  fr: "French",
  it: "Italian",
  ru: "Russian",
  ar: "Arabic",
  id: "Indonesian",
  ja: "Japanese",
  ko: "Korean",
  pl: "Polish",
  vi: "Vietnamese",
  th: "Thai",
  nl: "Dutch",
};

/** A partner code or the generic kit — the only things a kit URL may name. */
export function isKitCode(code: string): boolean {
  return code === GENERIC_KIT || CODE_RE.test(code);
}

export function isSafeKitFileName(name: string): boolean {
  return NAME_RE.test(name) && !name.includes("..") && kitExt(name) in KIT_CONTENT_TYPES;
}

function kitExt(name: string): string {
  const i = name.lastIndexOf(".");
  return i < 0 ? "" : name.slice(i + 1).toLowerCase();
}

export function kitContentType(name: string): string {
  return KIT_CONTENT_TYPES[kitExt(name)] ?? "application/octet-stream";
}

export type KitFile = { name: string; sizeBytes: number; updatedAt: string };

/** The whitelisted files in one kit folder (regular files, known types), sorted. [] when absent. */
export async function listKitFiles(code: string): Promise<KitFile[]> {
  if (!isKitCode(code)) return [];
  const dir = join(KITS_DIR, code);
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  const out: KitFile[] = [];
  for (const e of entries) {
    // Dirent.isFile() is false for a symlink, so a link pointing out of the
    // folder is never listed (and so can never be served).
    if (!e.isFile() || !isSafeKitFileName(e.name)) continue;
    try {
      const st = await fs.lstat(join(dir, e.name));
      if (!st.isFile() || st.size === 0) continue;
      out.push({ name: e.name, sizeBytes: st.size, updatedAt: st.mtime.toISOString() });
    } catch {
      /* vanished between readdir and stat */
    }
  }
  return out.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
}

/**
 * The absolute path of `name` in kit `code` — ONLY if it is in that kit's
 * directory listing (exact match). Anything else (traversal, absolute paths,
 * encoded separators, unknown files) is null.
 */
export async function resolveKitFile(code: string, name: string): Promise<{ path: string; file: KitFile } | null> {
  if (!isKitCode(code) || !isSafeKitFileName(name)) return null;
  const file = (await listKitFiles(code)).find((f) => f.name === name);
  return file ? { path: join(KITS_DIR, code, file.name), file } : null;
}

/* ── grouping ──────────────────────────────────────────────────────────── */

export type KitAsset = {
  /** Language tag from the file name, e.g. "en". */
  lang: string;
  langLabel: string;
  /** "16:9" from "16x9", or null. */
  aspect: string | null;
  video: KitFile;
  endframe: KitFile | null;
};

const ASSET_RE = /^(.+?)_([a-z]{2,3})_(\d{1,2}x\d{1,2})(_endframe)?\.([a-z0-9]+)$/i;
const VIDEO_EXT = new Set(["mp4", "webm", "mov"]);
const IMAGE_EXT = new Set(["png", "jpg", "jpeg", "webp"]);

export function groupKitAssets(files: KitFile[]): { assets: KitAsset[]; others: KitFile[] } {
  const videos = new Map<string, { m: RegExpExecArray; f: KitFile }>();
  const frames = new Map<string, KitFile>();
  const others: KitFile[] = [];
  for (const f of files) {
    if (f.name === GUIDE_FILE) continue;
    const m = ASSET_RE.exec(f.name);
    const ext = kitExt(f.name);
    if (!m) {
      others.push(f);
      continue;
    }
    const key = `${m[1]}_${m[2].toLowerCase()}_${m[3]}`;
    if (!m[4] && VIDEO_EXT.has(ext)) videos.set(key, { m, f });
    else if (m[4] && IMAGE_EXT.has(ext)) frames.set(key, f);
    else others.push(f);
  }
  const assets: KitAsset[] = [];
  for (const [key, { m, f }] of videos) {
    const lang = m[2].toLowerCase();
    assets.push({
      lang,
      langLabel: KIT_LANGUAGES[lang] ?? lang.toUpperCase(),
      aspect: m[3].replace("x", ":"),
      video: f,
      endframe: frames.get(key) ?? null,
    });
    frames.delete(key);
  }
  // An end frame with no video of its own is still a file the creator can use.
  others.push(...frames.values());
  // English first, then alphabetical by label.
  assets.sort((a, b) => (a.lang === "en" ? -1 : b.lang === "en" ? 1 : a.langLabel.localeCompare(b.langLabel)));
  return { assets, others: others.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)) };
}

/* ── HOW-TO-USE.txt ────────────────────────────────────────────────────── */

export type KitGuide = {
  title: string | null;
  /** File names listed under "Your files". */
  files: string[];
  /** Any prose under "Your files" (the generic cut explains itself there). */
  filesNote: string | null;
  whatItIs: string | null;
  steps: string[];
  /** The bracketed hint after "Suggested narration", e.g. "timings match the video…". */
  narrationNote: string | null;
  narration: { at: string; text: string }[];
  description: string | null;
  contact: string | null;
  /** Any section this parser doesn't know, kept rather than dropped. */
  extra: { heading: string; body: string }[];
};

type Section = { heading: string; inline: string | null; lines: string[] };

/** Joins wrapped, indented lines into paragraphs (a blank line splits them). */
function paragraphs(lines: string[]): string[] {
  const out: string[] = [];
  let cur: string[] = [];
  for (const l of lines) {
    const t = l.trim();
    if (!t) {
      if (cur.length) out.push(cur.join(" "));
      cur = [];
    } else cur.push(t);
  }
  if (cur.length) out.push(cur.join(" "));
  return out;
}

/**
 * Parses the owner's structured plain-text guide. Format: a title line with an
 * `====` underline, then sections whose heading starts in column 0 and whose
 * body is indented. "Heading: value" on one line is a one-line section.
 * Tolerant — an unknown section lands in `extra`, a missing one is empty.
 */
export function parseKitGuide(raw: string): KitGuide {
  const lines = raw.replace(/^﻿/, "").replace(/\r\n?/g, "\n").split("\n");
  const g: KitGuide = {
    title: null, files: [], filesNote: null, whatItIs: null, steps: [], narrationNote: null,
    narration: [], description: null, contact: null, extra: [],
  };
  const sections: Section[] = [];
  let i = 0;
  // Title + underline.
  while (i < lines.length && !lines[i].trim()) i++;
  if (i + 1 < lines.length && /^\s*={3,}\s*$/.test(lines[i + 1])) {
    g.title = lines[i].trim();
    i += 2;
  }
  for (; i < lines.length; i++) {
    const l = lines[i];
    if (/^\s*={3,}\s*$/.test(l)) continue;
    if (l.trim() && !/^\s/.test(l)) {
      const m = /^([^:]{1,80}):\s*(.+)$/.exec(l.trim());
      sections.push(m ? { heading: m[1].trim(), inline: m[2].trim(), lines: [] } : { heading: l.trim(), inline: null, lines: [] });
    } else if (sections.length) sections[sections.length - 1].lines.push(l);
  }

  for (const s of sections) {
    const h = s.heading.toLowerCase();
    if (h.startsWith("your files")) {
      const prose: string[] = [];
      for (const l of s.lines) {
        const m = /^\s*[-*•]\s+(.+)$/.exec(l);
        if (m) g.files.push(m[1].trim());
        else prose.push(l);
      }
      g.filesNote = paragraphs(prose).join("\n\n") || null;
    } else if (h.startsWith("what it is")) {
      g.whatItIs = paragraphs(s.lines).join("\n\n") || null;
    } else if (h.startsWith("how to use")) {
      for (const l of s.lines) {
        const m = /^\s*\d+[.)]\s+(.+)$/.exec(l);
        if (m) g.steps.push(m[1].trim());
        else if (l.trim() && g.steps.length) g.steps[g.steps.length - 1] += " " + l.trim();
      }
    } else if (h.startsWith("suggested narration") || h.startsWith("narration")) {
      const note = /\(([^)]+)\)/.exec(s.heading);
      g.narrationNote = note ? note[1].trim() : null;
      for (const l of s.lines) {
        const m = /^\s*(\d{1,2}:\d{2})\s+(.+)$/.exec(l);
        if (m) g.narration.push({ at: m[1], text: m[2].trim() });
        else if (l.trim() && g.narration.length) g.narration[g.narration.length - 1].text += " " + l.trim();
      }
    } else if (h.startsWith("description")) {
      g.description = paragraphs(s.lines).join("\n\n") || s.inline || null;
    } else if (h.startsWith("questions") || h.startsWith("contact")) {
      g.contact = s.inline ?? (paragraphs(s.lines).join(" ") || null);
    } else {
      const body = [s.inline, ...paragraphs(s.lines)].filter(Boolean).join("\n\n");
      if (body) g.extra.push({ heading: s.heading, body });
    }
  }
  return g;
}

/** Fills the generic guide's YOURCODE placeholder with the viewer's real code (display only). */
export function personalizeGuide(g: KitGuide, code: string): KitGuide {
  const r = (s: string | null) => (s == null ? s : s.replace(/YOURCODE/g, code));
  return {
    ...g,
    filesNote: r(g.filesNote),
    whatItIs: r(g.whatItIs),
    steps: g.steps.map((s) => r(s)!),
    narration: g.narration.map((n) => ({ ...n, text: r(n.text)! })),
    description: r(g.description),
    extra: g.extra.map((e) => ({ ...e, body: r(e.body)! })),
  };
}

/* ── one kit, ready for the UI ─────────────────────────────────────────── */

export type PartnerKit = {
  /** The folder: the partner's code, or "_generic". */
  code: string;
  assets: KitAsset[];
  others: KitFile[];
  guide: KitGuide | null;
  /** The raw guide file (for its download link), when present. */
  guideFile: KitFile | null;
  totalBytes: number;
  updatedAt: string | null;
};

const MAX_GUIDE_BYTES = 64 * 1024;

/** One kit folder, grouped + parsed; null when it doesn't exist or holds no video. */
export async function loadKit(code: string): Promise<PartnerKit | null> {
  const files = await listKitFiles(code);
  const { assets, others } = groupKitAssets(files);
  if (assets.length === 0) return null;
  const guideFile = files.find((f) => f.name === GUIDE_FILE) ?? null;
  let guide: KitGuide | null = null;
  if (guideFile && guideFile.sizeBytes <= MAX_GUIDE_BYTES) {
    try {
      guide = parseKitGuide(await fs.readFile(join(KITS_DIR, code, GUIDE_FILE), "utf8"));
    } catch {
      guide = null;
    }
  }
  return {
    code,
    assets,
    others,
    guide,
    guideFile,
    totalBytes: files.reduce((n, f) => n + f.sizeBytes, 0),
    updatedAt: files.reduce<string | null>((m, f) => (!m || f.updatedAt > m ? f.updatedAt : m), null),
  };
}

/**
 * What a partner sees: their own kit (null when none has been made yet or the
 * code isn't a valid kit folder name) and the generic one (YOURCODE filled in
 * with their code in the rendered guide; the raw download stays as-is).
 */
export async function loadPartnerKits(partnerCode: string): Promise<{ personal: PartnerKit | null; generic: PartnerKit | null }> {
  const code = partnerCode.trim().toUpperCase();
  const [personal, generic] = await Promise.all([
    CODE_RE.test(code) ? loadKit(code) : Promise.resolve(null),
    loadKit(GENERIC_KIT),
  ]);
  if (generic?.guide && CODE_RE.test(code)) generic.guide = personalizeGuide(generic.guide, code);
  return { personal, generic };
}

export { kitFileUrl, kitZipUrl } from "./partner-kit-urls";

/* ── streaming zip (STORE, no compression — MP4/PNG don't compress) ───── */

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32Update(crc: number, buf: Uint8Array): number {
  let c = crc ^ 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

// CRCs keyed by path+size+mtime, so a second download doesn't re-read 25 MB twice.
const crcCache = new Map<string, number>();

async function fileCrc32(path: string, f: KitFile): Promise<number> {
  const key = `${path}|${f.sizeBytes}|${f.updatedAt}`;
  const hit = crcCache.get(key);
  if (hit !== undefined) return hit;
  let crc = 0;
  const fh = await fs.open(path, "r");
  try {
    const buf = Buffer.allocUnsafe(1 << 20);
    for (;;) {
      const { bytesRead } = await fh.read(buf, 0, buf.length, null);
      if (!bytesRead) break;
      crc = crc32Update(crc, buf.subarray(0, bytesRead));
    }
  } finally {
    await fh.close();
  }
  if (crcCache.size > 200) crcCache.clear();
  crcCache.set(key, crc);
  return crc;
}

function dosDateTime(iso: string): { time: number; date: number } {
  const d = new Date(iso);
  const y = Math.max(1980, d.getUTCFullYear());
  return {
    time: (d.getUTCHours() << 11) | (d.getUTCMinutes() << 5) | Math.floor(d.getUTCSeconds() / 2),
    date: ((y - 1980) << 9) | ((d.getUTCMonth() + 1) << 5) | d.getUTCDate(),
  };
}

/**
 * A kit as a ZIP stream with an exact Content-Length. CRCs are computed first
 * (cached), so every local header carries real sizes — the most compatible
 * form (no data descriptors). Kits are tens of MB, far below the 4 GB ZIP32
 * limit; anything bigger is refused.
 */
export async function kitZip(code: string): Promise<{ stream: ReadableStream<Uint8Array>; size: number; filename: string } | null> {
  const files = await listKitFiles(code);
  if (files.length === 0) return null;
  const folder = code === GENERIC_KIT ? "nxeon-sponsored-segment-generic" : `nxeon-sponsored-segment-${code}`;
  const entries = await Promise.all(
    files.map(async (f) => {
      const path = join(KITS_DIR, code, f.name);
      return { f, path, crc: await fileCrc32(path, f), name: Buffer.from(`${folder}/${f.name}`, "utf8"), ...dosDateTime(f.updatedAt) };
    })
  );
  let offset = 0;
  const locals: Buffer[] = [];
  const offsets: number[] = [];
  for (const e of entries) {
    const h = Buffer.alloc(30);
    h.writeUInt32LE(0x04034b50, 0);
    h.writeUInt16LE(20, 4); // version needed
    h.writeUInt16LE(0x0800, 6); // UTF-8 names
    h.writeUInt16LE(0, 8); // STORE
    h.writeUInt16LE(e.time, 10);
    h.writeUInt16LE(e.date, 12);
    h.writeUInt32LE(e.crc, 14);
    h.writeUInt32LE(e.f.sizeBytes, 18);
    h.writeUInt32LE(e.f.sizeBytes, 22);
    h.writeUInt16LE(e.name.length, 26);
    h.writeUInt16LE(0, 28);
    const local = Buffer.concat([h, e.name]);
    locals.push(local);
    offsets.push(offset);
    offset += local.length + e.f.sizeBytes;
  }
  const central: Buffer[] = entries.map((e, idx) => {
    const c = Buffer.alloc(46);
    c.writeUInt32LE(0x02014b50, 0);
    c.writeUInt16LE(20, 4); // version made by
    c.writeUInt16LE(20, 6);
    c.writeUInt16LE(0x0800, 8);
    c.writeUInt16LE(0, 10);
    c.writeUInt16LE(e.time, 12);
    c.writeUInt16LE(e.date, 14);
    c.writeUInt32LE(e.crc, 16);
    c.writeUInt32LE(e.f.sizeBytes, 20);
    c.writeUInt32LE(e.f.sizeBytes, 24);
    c.writeUInt16LE(e.name.length, 28);
    c.writeUInt32LE(0, 30); // extra + comment length
    c.writeUInt32LE(0, 34); // disk + internal attrs
    c.writeUInt32LE(0, 38); // external attrs
    c.writeUInt32LE(offsets[idx], 42);
    return Buffer.concat([c, e.name]);
  });
  const cdSize = central.reduce((n, b) => n + b.length, 0);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(cdSize, 12);
  end.writeUInt32LE(offset, 16);
  const size = offset + cdSize + end.length;
  if (size >= 0xffffffff) return null;

  let idx = 0;
  let fh: import("node:fs/promises").FileHandle | null = null;
  let remaining = 0;
  let tailSent = false;
  const buf = Buffer.allocUnsafe(1 << 18);
  const stream = new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        // Every pull must enqueue or close — a pull that returns with nothing
        // queued is never called again, so step past finished files in a loop.
        while (idx < entries.length) {
          if (!fh) {
            controller.enqueue(new Uint8Array(locals[idx]));
            fh = await fs.open(entries[idx].path, "r");
            remaining = entries[idx].f.sizeBytes;
            return;
          }
          // Never more than the size the headers promised (Content-Length stays exact).
          const { bytesRead } = remaining > 0 ? await fh.read(buf, 0, Math.min(buf.length, remaining), null) : { bytesRead: 0 };
          if (bytesRead) {
            remaining -= bytesRead;
            controller.enqueue(new Uint8Array(buf.subarray(0, bytesRead)));
            return;
          }
          await fh.close();
          fh = null;
          if (remaining > 0) throw new Error(`kit file shrank while zipping: ${entries[idx].f.name}`);
          idx++;
        }
        if (!tailSent) {
          tailSent = true;
          controller.enqueue(new Uint8Array(Buffer.concat([...central, end])));
          return;
        }
        controller.close();
      } catch (err) {
        if (fh) await fh.close().catch(() => {});
        fh = null;
        controller.error(err);
      }
    },
    async cancel() {
      if (fh) await fh.close().catch(() => {});
      fh = null;
    },
  });
  return { stream, size, filename: `${folder}.zip` };
}

