export function applyPartnerDiscount(
  amountCents: number,
  tier: PartnerDiscountTier,
): { discountCents: number; netCents: number; tier: PartnerDiscountTier } {
  const discountCents = partnerDiscountCentsFor(amountCents, partnerDiscountPercentForTier(tier));
  return {
    discountCents,
    netCents: Math.max(0, amountCents) - discountCents,
    tier: discountCents > 0 ? tier : "NONE",
  };
}

