export type GameOrderPrice = {
  chargeCents: number;
  /** Creator Partner Program discount INSIDE `chargeCents`, and its tier, as
   *  sold (2026-09-28). Fulfilment re-quotes WITHOUT the coupon (the intent
   *  stamped on the session does not carry it — the hold token does), so the
   *  fresh quote's partner figure is computed on the pre-coupon price; the
   *  invoice's partner line must use what was actually sold. Optional: absent
   *  on sessions created before this field existed (falls back to the quote). */
  partnerDiscountCents?: number;
  partnerDiscountTier?: "FIRST" | "RECURRING" | "NONE";
