#!/usr/bin/env node
/* After rendering: write each creator's kit next to their videos.
   - HOW-TO-USE.txt  (where to place it, disclosure, a timed narration script, description text)
   - an end-frame PNG per video (last held frame, for thumbnails / pinned posts)

   node tools/creator-kit.mjs              # every creator folder under renders/creators/
   node tools/creator-kit.mjs --only KOBBI */
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const only = args.includes("--only") ? args[args.indexOf("--only") + 1].toUpperCase().split(",") : null;
const OUT = join(ROOT, "renders", "creators");

function csvRows() {
  const [head, ...rows] = readFileSync(join(ROOT, "creators.csv"), "utf8").split(/\r?\n/).filter((l) => l.trim() && !l.startsWith("#")).map((l) => l.split(",").map((c) => c.trim()));
  return rows.map((r) => Object.fromEntries(head.map((h, i) => [h, r[i] || ""])));
}

function note(code, url, d1, d2, files) {
  return `NXEON SPONSORED SEGMENT · code ${code}
${"=".repeat(44)}

Your files
${files.map((f) => "  - " + f).join("\n")}

What it is
  A 50-second sponsored segment showing the real Nxeon game-server flow:
  pick a game, region, your code at checkout, deploy, then the control panel
  (settings, 1-click mods, resources, upgrades). It has no audio, so you can
  talk over it and use your own music. Each screen animates in fast and then
  holds, which leaves room to narrate.

How to use it
  1. Drop the MP4 into your edit wherever the sponsor read goes (mid-roll works best).
  2. Tick YouTube's "Includes paid promotion" box (Details > Paid promotion).
     The small "SPONSORED" tag in the corner is extra and doesn't replace it.
  3. Say your code out loud on the end card: it holds still for the last ~3.5 s.
  4. Put the link and code in your description (text below).

Suggested narration (timings match the video, so make it your own)
  0:00  This video is sponsored by Nxeon.
  0:02  If you want your own game server, Nxeon gets you there in seconds. Pick your game,
  0:06  choose a region close to your players,
  0:10  and at checkout use my code ${code}: that's ${d1}% off your first server,
        and ${d2}% off everything after that, for life.
  0:16  One click to deploy,
  0:18  and your server builds itself and goes live.
  0:23  Everything is in one control panel:
  0:28  tweak any setting,
  0:31  install mods in one click,
  0:36  keep an eye on your resources,
  0:39  and upgrade instantly when your world grows.
  0:43  Go to nxeon.cloud/partner/${code}, or use code ${code} for ${d1}% off your first server.
        The link is in the description.

Description text
  This video is sponsored by Nxeon. Get ${d1}% off your first game server
  (then ${d2}% off for life) with code ${code}: https://${url}

Questions: santino@nxeon.cloud
`;
}

const rows = Object.fromEntries(csvRows().map((r) => [String(r.code).toUpperCase(), r]));
if (!existsSync(OUT)) { console.error("No renders yet (renders/creators/ is missing)."); process.exit(1); }
for (const code of readdirSync(OUT)) {
  if (only && !only.includes(code)) continue;
  const dir = join(OUT, code), mp4s = readdirSync(dir).filter((f) => f.endsWith(".mp4") && !f.includes("_draft"));
  if (!mp4s.length) continue;
  const r = rows[code] || {};
  const url = String(r.url || `nxeon.cloud/partner/${code}`).replace(/^https?:\/\//, "");
  const pngs = [];
  for (const f of mp4s) {
    const png = f.replace(/\.mp4$/, "_endframe.png");
    const res = spawnSync("ffmpeg", ["-v", "error", "-y", "-sseof", "-0.1", "-i", join(dir, f), "-frames:v", "1", join(dir, png)], { stdio: "inherit" });
    if (res.status === 0) pngs.push(png);
  }
  writeFileSync(join(dir, "HOW-TO-USE.txt"), note(code, url, r.discountFirst || 50, r.discountAfter || 10, [...mp4s, ...pngs]));
  console.log(`${code}: ${mp4s.length} video(s), ${pngs.length} end frame(s), HOW-TO-USE.txt`);
}

"use client";

