// CREATOR PROMO VIDEOS — pure, dependency-free core (2026-10-08).
//
// Shared by THREE runtimes, so it imports nothing at all:
//   - the app (lib/promo.ts, the /api/promo routes, the partner card — client-safe),
//   - the node-2 render worker (worker-render/promo-worker.ts, run by plain
//     `node` with type stripping, so only erasable TypeScript syntax here:
//     no enums, no namespaces, no parameter properties),
//   - the unit tests (test/promo.test.ts).
//
// The video template is video-templates/creator-promo (HyperFrames). The app
// never imports it; it builds the JSON variables below and the worker shells
// out to the HyperFrames CLI. See docs/DOCUMENTATION.md "Creator promo videos".

/** Bump whenever video-templates/creator-promo changes visually (or its variables) — cached renders regenerate. */
export const PROMO_TEMPLATE_VERSION = "1.1.0";
/** The HyperFrames CLI version the template is built and checked against. */
export const PROMO_HYPERFRAMES_VERSION = "0.8.140";

export const PROMO_LANGS = { en: "English", es: "Español", tr: "Türkçe", hi: "हिन्दी", tl: "Tagalog" } as const;
export type PromoLang = keyof typeof PROMO_LANGS;
export const PROMO_FORMATS = ["16x9", "9x16", "overlays"] as const;
export type PromoFormat = (typeof PROMO_FORMATS)[number];
export const PROMO_FORMAT_LABELS: Record<PromoFormat, string> = { "16x9": "16:9 video", "9x16": "9:16 video", overlays: "Overlay kit" };

export const PROMO_MAX_HANDLE = 30;
const CODE_RE = /^[A-Z0-9_-]{2,16}$/;

export function isPromoLang(v: unknown): v is PromoLang {
  return typeof v === "string" && Object.prototype.hasOwnProperty.call(PROMO_LANGS, v);
}
export function isPromoFormat(v: unknown): v is PromoFormat {
  return typeof v === "string" && (PROMO_FORMATS as readonly string[]).includes(v);
}

/** A partner code as the template renders it, or null if it can't be shown faithfully (the template would strip characters). */
export function promoCode(raw: string): string | null {
  const code = raw.trim().toUpperCase();
  return CODE_RE.test(code) ? code : null;
}

/** "@ArmyOfZeus " → "ArmyOfZeus": letters, digits, _ . - only, max 30. */
export function cleanPromoHandle(raw: unknown): string {
  return String(raw ?? "").trim().replace(/^@+/, "").replace(/[^A-Za-z0-9_.-]/g, "").slice(0, PROMO_MAX_HANDLE);
}

/**
 * App game family (lib/games.ts GameFamily) → the template's `game` key. Only
 * these families have a cover + name mapping in the template (src/data.js
 * NX.GAMES); anything else is not offered. A mapped family is still hidden
 * when its live plans can't be priced (see pickPromoTiers).
 */
export const PROMO_GAME_KEY: Record<string, string> = {
  minecraft: "minecraft",
  bedrock: "minecraft-bedrock",
  valheim: "valheim",
  rust: "rust",
  palworld: "palworld",
  terraria: "terraria",
  projectzomboid: "project-zomboid",
  factorio: "factorio",
  theforest: "the-forest",
  enshrouded: "enshrouded",
};

/* ── pricing from the live catalog ─────────────────────────────────────── */

/** The fields of a GamePlan row pricing needs. */
export type PromoPlanRow = {
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  priceCents: number;
  termMonths: number;
  introPriceCents?: number | null;
  introTermMonths?: number | null;
};

/** The template's upgrade beat shows exactly these three tiers ("<Game> — 2/4/8 GB"). */
export const PROMO_TIER_RAM = { 2: 2048, 4: 4096, 8: 8192 } as const;

/**
 * The family's 2 / 4 / 8 GB monthly tiers out of its ACTIVE plans, or null when
 * any is missing — that game is then hidden from the generator rather than
 * rendered with numbers that aren't real. Several plans at one size: the
 * cheapest wins (the one a customer would see first).
 */
export function pickPromoTiers<T extends PromoPlanRow>(plans: T[]): { t2: T; t4: T; t8: T } | null {
  const at = (ram: number): T | null => {
    const hits = plans.filter((p) => p.ramMB === ram && p.termMonths === 1 && p.priceCents > 0);
    hits.sort((a, b) => a.priceCents - b.priceCents);
    return hits[0] ?? null;
  };
  const t2 = at(PROMO_TIER_RAM[2]);
  const t4 = at(PROMO_TIER_RAM[4]);
  const t8 = at(PROMO_TIER_RAM[8]);
  return t2 && t4 && t8 ? { t2, t4, t8 } : null;
}

/** "$4.99" — USD, symbol first, 2 decimals. Catalog prices are integer USD cents. */
export function promoUsd(cents: number): string {
  return "$" + (Math.max(0, Math.round(cents)) / 100).toFixed(2);
}

/** The intro (first-month) price when it is genuinely below the regular one — mirrors lib/intro-pricing.ts planIntroMonthlyCents. */
export function introMonthly(p: PromoPlanRow): number | null {
  const v = p.introPriceCents;
  if (typeof v !== "number" || !Number.isFinite(v) || v < 0) return null;
  const c = Math.round(v);
  return c < p.priceCents ? c : null;
}

/** The share of the monthly difference the upgrade beat shows as "due now" — illustrative (21 of 30 days left), matching the portal recording. */
export const PROMO_UPGRADE_REMAINING = 0.7;

export type PromoPricing = {
  priceBefore: string;
  priceAfter: string;
  renewPrice: string;
  upgradePrice: string;
  upgradeRenew: string;
  tier8Price: string;
  tierCpu2: number; tierDisk2: number; tierPlayers2: number;
  tierCpu4: number; tierDisk4: number; tierPlayers4: number;
  tierCpu8: number; tierDisk8: number; tierPlayers8: number;
};

/**
 * Video prices + specs from three live tiers.
 *   priceBefore  = entry tier's first-month price (its intro price if it has one, else its monthly price)
 *   priceAfter   = priceBefore minus the first-purchase partner discount, rounded exactly like
 *                  lib/partner-discount.ts partnerDiscountCentsFor (the real checkout)
 *   renewPrice   = entry tier monthly; upgradeRenew = 4 GB monthly; tier8Price = 8 GB monthly
 *   upgradePrice = PROMO_UPGRADE_REMAINING × (4 GB − 2 GB monthly), the "pay only the difference" beat
 * `players(plan)` is lib/game-player-capacity.ts recommendedPlayers (0 = not shown).
 */
export function promoPricingFromTiers<T extends PromoPlanRow>(
  tiers: { t2: T; t4: T; t8: T },
  discountFirstPct: number,
  players: (p: T) => number | null,
): PromoPricing {
  const { t2, t4, t8 } = tiers;
  const first = introMonthly(t2) ?? t2.priceCents;
  const pct = Math.max(0, Math.min(100, discountFirstPct));
  const after = first - Math.round((first * pct) / 100);
  const diff = Math.max(0, t4.priceCents - t2.priceCents);
  const p = (x: T) => Math.max(0, Math.round(players(x) ?? 0));
  return {
    priceBefore: promoUsd(first),
    priceAfter: promoUsd(after),
    renewPrice: promoUsd(t2.priceCents),
    upgradePrice: promoUsd(Math.round(diff * PROMO_UPGRADE_REMAINING)),
    upgradeRenew: promoUsd(t4.priceCents),
    tier8Price: promoUsd(t8.priceCents),
    tierCpu2: t2.cpuCores, tierDisk2: t2.diskGB, tierPlayers2: p(t2),
    tierCpu4: t4.cpuCores, tierDisk4: t4.diskGB, tierPlayers4: p(t4),
    tierCpu8: t8.cpuCores, tierDisk8: t8.diskGB, tierPlayers8: p(t8),
  };
}

/* ── the variables file ────────────────────────────────────────────────── */

export type PromoVars = PromoPricing & {
  code: string;
  lang: PromoLang;
  game: string;
  discountFirst: number;
  discountAfter: number;
  url: string;
  creatorHandle: string;
  gamesCount: number;
  sponsoredTag: boolean;
};

/** Stable JSON (sorted keys) so identical requests hash identically. */
export function stableJson(o: unknown): string {
  const sort = (x: unknown): unknown =>
    Array.isArray(x)
      ? x.map(sort)
      : x && typeof x === "object"
        ? Object.fromEntries(Object.keys(x as Record<string, unknown>).sort().map((k) => [k, sort((x as Record<string, unknown>)[k])]))
        : x;
  return JSON.stringify(sort(o));
}

/** What gets hashed into PromoRender.cacheKey (sha256 of this string — hashing itself lives in lib/promo.ts). */
export function promoCacheMaterial(vars: Record<string, unknown>, formats: readonly string[], version = PROMO_TEMPLATE_VERSION): string {
  return stableJson({ v: version, vars, fmts: [...new Set(formats)].sort() });
}

export function normalizeFormats(raw: unknown): PromoFormat[] {
  const list = Array.isArray(raw) ? raw : typeof raw === "string" ? raw.split(",") : [];
  const out = [...new Set(list.map((x) => String(x).trim()).filter(isPromoFormat))];
  // Fixed order (also the render order): 16:9, 9:16, overlays.
  return PROMO_FORMATS.filter((f) => out.includes(f));
}

/* ── the files one render produces ─────────────────────────────────────── */

export type PromoFileKind = "video" | "overlay" | "image" | "text";
export type PromoTask = { label: string; out: string; args: string[]; endframe: string | null; estSec: number };

export const PROMO_GUIDE_FILE = "HOW-TO-USE.txt";

/**
 * The render tasks for one PromoRender, in order: each is one HyperFrames CLI
 * call (args AFTER `render --strict-variables --variables-file <f> -o <out>`).
 * File names follow the media-kit convention (lib/partner-kits.ts groupKitAssets):
 *   nxeon-promo_<CODE>_<lang>_<16x9|9x16>.mp4 (+ _endframe.png), nxeon-overlay_<kind>_<CODE>.mov
 * `estSec` is a measured-on-node-2 estimate used only for the progress bar.
 */
export function promoTasks(vars: { code: string; lang: string }, formats: readonly string[]): PromoTask[] {
  const code = promoCode(vars.code);
  if (!code || !isPromoLang(vars.lang)) throw new Error("bad promo vars");
  const lang = vars.lang;
  const want = normalizeFormats([...formats]);
  const tasks: PromoTask[] = [];
  if (want.includes("16x9")) {
    const out = `nxeon-promo_${code}_${lang}_16x9.mp4`;
    tasks.push({ label: "16:9 video", out, args: ["-f", "60", "-q", "high"], endframe: out.replace(/\.mp4$/, "_endframe.png"), estSec: 330 });
  }
  if (want.includes("9x16")) {
    const out = `nxeon-promo_${code}_${lang}_9x16.mp4`;
    tasks.push({ label: "9:16 video", out, args: ["-f", "60", "-q", "high", "--composition", "compositions/vertical.html"], endframe: out.replace(/\.mp4$/, "_endframe.png"), estSec: 330 });
  }
  if (want.includes("overlays")) {
    for (const k of ["sting", "code", "endcard"]) {
      tasks.push({ label: `overlay: ${k}`, out: `nxeon-overlay_${k}_${code}.mov`, args: ["--format", "mov", "-f", "60", "--composition", `compositions/overlay-${k}.html`], endframe: null, estSec: 90 });
    }
  }
  return tasks;
}

/** Upload size caps per kind (bytes). The end-card ProRes overlay alone is ~650 MB. */
export const PROMO_MAX_BYTES: Record<PromoFileKind, number> = {
  video: 600 * 1024 * 1024,
  overlay: 2 * 1024 * 1024 * 1024,
  image: 25 * 1024 * 1024,
  text: 256 * 1024,
};

export function promoFileKind(name: string): PromoFileKind {
  if (name.endsWith(".mov")) return "overlay";
  if (name.endsWith(".mp4")) return "video";
  if (name.endsWith(".png")) return "image";
  return "text";
}

/** Exactly the files the WORKER uploads for this render (the app writes HOW-TO-USE.txt itself). */
export function expectedWorkerFiles(vars: { code: string; lang: string }, formats: readonly string[]): { name: string; kind: PromoFileKind }[] {
  const out: { name: string; kind: PromoFileKind }[] = [];
  for (const t of promoTasks(vars, formats)) {
    out.push({ name: t.out, kind: promoFileKind(t.out) });
    if (t.endframe) out.push({ name: t.endframe, kind: "image" });
  }
  return out;
}

export const PROMO_CHUNK_BYTES = 8 * 1024 * 1024;

export function promoContentType(name: string): string {
  if (name.endsWith(".mp4")) return "video/mp4";
  if (name.endsWith(".mov")) return "video/quicktime";
  if (name.endsWith(".png")) return "image/png";
  return "text/plain; charset=utf-8";
}

/* ── UI-facing shapes (serialised to the partner card / admin) ─────────── */

export type PromoFileView = { name: string; kind: PromoFileKind; bytes: number };
export type PromoRenderView = {
  id: string;
  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED" | "EXPIRED";
  progress: number;
  step: string | null;
  error: string | null;
  formats: PromoFormat[];
  files: PromoFileView[];
  lang: string;
  gameName: string;
  handle: string;
  createdAt: string;
  finishedAt: string | null;
  expiresAt: string | null;
};
export type PromoGameOption = { family: string; name: string };
export type PromoState = {
  code: string;
  games: PromoGameOption[];
  renders: PromoRenderView[];
  usedToday: number;
  maxPerDay: number;
  /** When the oldest render in the rolling 24 h window drops out (only when the limit is reached). */
  nextSlotAt: string | null;
  retentionDays: number;
};

export function promoFileUrl(renderId: string, name: string, download = false): string {
  return `/api/promo/${encodeURIComponent(renderId)}/file/${encodeURIComponent(name)}${download ? "?download=1" : ""}`;
}

