// HOW-TO-USE.txt for a generated creator promo video (lib/promo.ts). Pure.
//
// Ported from the template's own tools/creator-kit.mjs note() so a generated
// render ships the same guide as an owner-made media kit — and in the same
// structured plain-text format lib/partner-kits.ts parseKitGuide() reads
// (title + ==== underline, column-0 headings, indented bodies). The app writes
// this file itself when the worker reports DONE (app/api/promo/worker/[id]/done),
// from the render's own stored variables: never from anything the worker sends.

export type HowToVars = { code: string; url: string; discountFirst: number; discountAfter: number; creatorHandle?: string };

export function howToUse(v: HowToVars, files: string[]): string {
  const { code, url } = v;
  const d1 = v.discountFirst;
  const d2 = v.discountAfter;
  const title = `NXEON SPONSORED SEGMENT · code ${code}`;
  return `${title}
${"=".repeat(Math.max(44, title.length))}

Your files
${files.map((f) => "  - " + f).join("\n")}

What it is
  A 50-second sponsored segment showing the real Nxeon game-server flow:
  pick a game, region, your code at checkout, deploy, then the control panel
  (settings, 1-click mods, resources, upgrades). It has no audio, so you can
  talk over it and use your own music. Each screen animates in fast and then
  holds, which leaves room to narrate.

How to use it
  1. Drop the MP4 into your edit wherever the sponsor read goes (mid-roll works best).
  2. Tick YouTube's "Includes paid promotion" box (Details > Paid promotion).
     The small "SPONSORED" tag in the corner is extra and doesn't replace it.
  3. Say your code out loud on the end card: it holds still for the last ~3.5 s.
  4. Put the link and code in your description (text below).
  5. If you picked a language other than English, have a native speaker check
     the on-screen text before you publish.

Suggested narration (timings match the video, so make it your own)
  0:00  This video is sponsored by Nxeon.
  0:02  If you want your own game server, Nxeon gets you there in seconds. Pick your game,
  0:06  choose a region close to your players,
  0:10  and at checkout use my code ${code}: that's ${d1}% off your first server,
        and ${d2}% off everything after that, for life.
  0:16  One click to deploy,
  0:18  and your server builds itself and goes live.
  0:23  Everything is in one control panel:
  0:28  tweak any setting,
  0:31  install mods in one click,
  0:36  keep an eye on your resources,
  0:39  and upgrade instantly when your world grows.
  0:43  Go to ${url}, or use code ${code} for ${d1}% off your first server.
        The link is in the description.

Description text
  This video is sponsored by Nxeon. Get ${d1}% off your first game server
  (then ${d2}% off for life) with code ${code}: https://${url}

Questions: open a ticket from Support in your Nxeon dashboard.
`;
}

