// CREATOR PROMO VIDEOS — server-side helpers (2026-10-08).
//
// Every Creator Partner can generate their own sponsored-segment video (their
// code, language and game) from the partner portal's Media kit tab. The app
// only builds the template's JSON variables from the DATABASE (code, partner
// URL, live prices, the program's real discount) and queues a PromoRender row;
// rendering happens on node-2 (worker-render/promo-worker.ts), which never sees
// a database credential — it claims work and uploads files through the
// secret-authenticated pull API (lib/promo-worker.ts, /api/promo/worker/*).
//
// Inert until PROMO_WORKER_SECRET is set: no card, no API, no queue.
// Full write-up: docs/DOCUMENTATION.md "Creator promo videos".

import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import { join } from "node:path";
import type { PromoRender } from "@prisma/client";
import { db } from "@/lib/db";
import { GAME_DISPLAY, GAME_FAMILIES, type GameFamily } from "@/lib/games";
import { PARTNER_FIRST_PURCHASE_PCT, PARTNER_RECURRING_PCT } from "@/lib/partner-discount";
import { recommendedPlayers } from "@/lib/game-player-capacity";
import {
  PROMO_GAME_KEY,
  PROMO_LANGS,
  PROMO_TEMPLATE_VERSION,
  cleanPromoHandle,
  isPromoLang,
  normalizeFormats,
  pickPromoTiers,
  promoCacheMaterial,
  promoCode,
  promoFileKind,
  promoPricingFromTiers,
  type PromoFileView,
  type PromoFormat,
  type PromoGameOption,
  type PromoLang,
  type PromoPricing,
  type PromoRenderView,
  type PromoState,
  type PromoVars,
} from "@/lib/promo-core";

export class PromoError extends Error {}

/* ── config ────────────────────────────────────────────────────────────── */

export const PROMO_RENDER_DIR = process.env.PROMO_RENDER_DIR ?? "/var/lib/nxeon/promo-renders";
const num = (v: string | undefined, d: number) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : d;
};
export const PROMO_MAX_PER_DAY = num(process.env.PROMO_MAX_PER_DAY, 6);
export const PROMO_RETENTION_DAYS = num(process.env.PROMO_RETENTION_DAYS, 14);
/** New requests are refused while finished renders on disk exceed this. */
export const PROMO_DISK_MAX_BYTES = num(process.env.PROMO_DISK_MAX_GB, 60) * 1024 ** 3;

/** The feature is ON only when the worker secret is configured (min 32 chars). */
export function promoEnabled(): boolean {
  return (process.env.PROMO_WORKER_SECRET ?? "").length >= 32;
}

/* ── games + prices from the live catalog ──────────────────────────────── */

/**
 * The video's prices and tier specs for one game family, read from its ACTIVE
 * GamePlan rows (the same rows the deploy wizard sells). Null when the family
 * lacks a monthly 2 GB, 4 GB or 8 GB tier: the upgrade beat shows exactly those
 * three, so such a game is hidden rather than shown with made-up numbers.
 */
export async function promoPricing(family: string, discountFirstPct: number): Promise<PromoPricing | null> {
  if (!PROMO_GAME_KEY[family]) return null;
  const plans = await db.gamePlan.findMany({
    where: { gameFamily: family, active: true },
    select: { ramMB: true, cpuCores: true, diskGB: true, priceCents: true, termMonths: true, introPriceCents: true, introTermMonths: true },
  });
  const tiers = pickPromoTiers(plans);
  if (!tiers) return null;
  return promoPricingFromTiers(tiers, discountFirstPct, (p) => recommendedPlayers(family, p));
}

/** The games a partner can pick: template-mapped families that price cleanly today. */
export async function promoGames(): Promise<PromoGameOption[]> {
  const out: PromoGameOption[] = [];
  for (const family of Object.keys(PROMO_GAME_KEY)) {
    if (await promoPricing(family, PARTNER_FIRST_PURCHASE_PCT)) {
      out.push({ family, name: GAME_DISPLAY[family as GameFamily]?.name ?? family });
    }
  }
  return out;
}

/** "N supported games" on the end card: families with an active plan — the same count the deploy wizard shows. */
export async function promoGamesCount(): Promise<number> {
  const rows = await db.gamePlan.groupBy({ by: ["gameFamily"], where: { active: true } });
  return rows.filter((r) => (GAME_FAMILIES as readonly string[]).includes(r.gameFamily)).length;
}

function appHost(): string {
  try {
    return new URL(process.env.APP_URL ?? "https://nxeon.cloud").host;
  } catch {
    return "nxeon.cloud";
  }
}

/**
 * The template's variables, entirely from the DB: the partner's real code and
 * /partner/<CODE> link, the program's fixed discounts (lib/partner-discount.ts),
 * live prices and specs. Only `lang`, `family` and the optional on-screen
 * `handle` come from the request, each validated against an allow-list.
 */
export async function buildPromoVars(
  partner: { code: string },
  o: { lang: string; family: string; handle?: string },
): Promise<PromoVars> {
  const code = promoCode(partner.code);
  if (!code) throw new PromoError("This partner code can't be used in a video (A–Z, 0–9, _ or -, 2–16 characters).");
  if (!isPromoLang(o.lang)) throw new PromoError("Pick one of the offered languages.");
  const game = PROMO_GAME_KEY[o.family];
  if (!game) throw new PromoError("That game isn't available for promo videos yet.");
  const d1 = PARTNER_FIRST_PURCHASE_PCT;
  const d2 = PARTNER_RECURRING_PCT;
  const pricing = await promoPricing(o.family, d1);
  if (!pricing) throw new PromoError("Pricing for this game isn't available right now, so it can't be shown in a video.");
  return {
    code,
    lang: o.lang,
    game,
    discountFirst: d1,
    discountAfter: d2,
    ...pricing,
    url: `${appHost()}/partner/${code}`,
    creatorHandle: cleanPromoHandle(o.handle),
    gamesCount: await promoGamesCount(),
    sponsoredTag: true,
  };
}

export function promoCacheKey(vars: Record<string, unknown>, formats: readonly string[], version = PROMO_TEMPLATE_VERSION): string {
  return createHash("sha256").update(promoCacheMaterial(vars, formats, version)).digest("hex");
}

/* ── queueing ──────────────────────────────────────────────────────────── */

const DAY_MS = 86_400_000;

async function selfServeWindow(partnerId: string, requestedById: string | null) {
  if (!requestedById) return [];
  return db.promoRender.findMany({
    where: { partnerId, requestedById, createdAt: { gte: new Date(Date.now() - DAY_MS) } },
    select: { createdAt: true },
    orderBy: { createdAt: "asc" },
  });
}

async function finishedBytesOnDisk(): Promise<number> {
  const rows = await db.promoRender.findMany({ where: { status: "DONE" }, select: { files: true } });
  let n = 0;
  for (const r of rows) for (const f of fileList(r.files)) n += f.bytes;
  return n;
}

/**
 * Idempotent: an identical request (same template version, variables and
 * formats) returns the partner's existing QUEUED/RUNNING/DONE render. Otherwise
 * a new row, rate-limited to PROMO_MAX_PER_DAY self-serve renders per rolling
 * 24 h (admin batches bypass it) and refused while the render store is full.
 */
export async function requestPromo(
  partnerId: string,
  requestedById: string | null,
  vars: PromoVars,
  formats: PromoFormat[],
  opts?: { bypassLimit?: boolean },
): Promise<{ render: PromoRender; reused: boolean }> {
  if (!promoEnabled()) throw new PromoError("Promo videos aren't available yet.");
  const fmts = normalizeFormats(formats);
  if (fmts.length === 0) throw new PromoError("Pick at least one format.");
  const cacheKey = promoCacheKey(vars, fmts);
  const existing = await db.promoRender.findFirst({
    where: { partnerId, cacheKey, status: { in: ["QUEUED", "RUNNING", "DONE"] } },
    orderBy: { createdAt: "desc" },
  });
  if (existing) return { render: existing, reused: true };
  if (!opts?.bypassLimit) {
    const recent = await selfServeWindow(partnerId, requestedById);
    if (recent.length >= PROMO_MAX_PER_DAY) throw new PromoError("Daily video limit reached. Try again tomorrow.");
  }
  if ((await finishedBytesOnDisk()) >= PROMO_DISK_MAX_BYTES) {
    throw new PromoError("Video generation is paused for a moment while we make room. Please try again later.");
  }
  const render = await db.promoRender.create({
    data: {
      partnerId,
      requestedById,
      cacheKey,
      templateVersion: PROMO_TEMPLATE_VERSION,
      vars: vars as unknown as object,
      formats: fmts.join(","),
    },
  });
  return { render, reused: false };
}

/* ── views ─────────────────────────────────────────────────────────────── */

export function fileList(raw: unknown): PromoFileView[] {
  if (!Array.isArray(raw)) return [];
  const out: PromoFileView[] = [];
  for (const f of raw) {
    if (!f || typeof f !== "object") continue;
    const { name, bytes } = f as Record<string, unknown>;
    if (typeof name !== "string" || typeof bytes !== "number") continue;
    out.push({ name, kind: promoFileKind(name), bytes });
  }
  return out;
}

const GAME_NAME_BY_KEY: Record<string, string> = Object.fromEntries(
  Object.entries(PROMO_GAME_KEY).map(([family, key]) => [key, GAME_DISPLAY[family as GameFamily]?.name ?? family]),
);

export function promoRenderView(r: PromoRender): PromoRenderView {
  const v = (r.vars ?? {}) as Record<string, unknown>;
  const lang = typeof v.lang === "string" ? v.lang : "en";
  const status = (["QUEUED", "RUNNING", "DONE", "FAILED", "EXPIRED"].includes(r.status) ? r.status : "FAILED") as PromoRenderView["status"];
  return {
    id: r.id,
    status,
    progress: Math.max(0, Math.min(100, r.progress)),
    step: r.step,
    // A worker error can carry paths/CLI noise; partners see a plain line, admins the detail (admin view reads the row).
    error: status === "FAILED" ? "The render didn't finish. Try again, or contact Support if it keeps failing." : null,
    formats: normalizeFormats(r.formats),
    files: status === "DONE" ? fileList(r.files) : [],
    lang: PROMO_LANGS[lang as PromoLang] ?? lang,
    gameName: GAME_NAME_BY_KEY[String(v.game)] ?? String(v.game ?? ""),
    handle: typeof v.creatorHandle === "string" ? v.creatorHandle : "",
    createdAt: r.createdAt.toISOString(),
    finishedAt: r.finishedAt?.toISOString() ?? null,
    expiresAt: status === "DONE" && r.finishedAt ? new Date(r.finishedAt.getTime() + PROMO_RETENTION_DAYS * DAY_MS).toISOString() : null,
  };
}

/** Everything the partner card needs, server-rendered (then polled via GET /api/promo while a render is active). */
export async function promoStateFor(partner: { id: string; code: string; userId: string | null }): Promise<PromoState | null> {
  if (!promoEnabled()) return null;
  const code = promoCode(partner.code);
  if (!code) return null;
  const [games, rows, recent] = await Promise.all([
    promoGames(),
    db.promoRender.findMany({ where: { partnerId: partner.id }, orderBy: { createdAt: "desc" }, take: 10 }),
    selfServeWindow(partner.id, partner.userId),
  ]);
  const full = recent.length >= PROMO_MAX_PER_DAY;
  return {
    code,
    games,
    renders: rows.map(promoRenderView),
    usedToday: recent.length,
    maxPerDay: PROMO_MAX_PER_DAY,
    nextSlotAt: full ? new Date(recent[0].createdAt.getTime() + DAY_MS).toISOString() : null,
    retentionDays: PROMO_RETENTION_DAYS,
  };
}

/* ── files on disk ─────────────────────────────────────────────────────── */

/**
 * The absolute path of a finished render's file — ONLY if `name` is in the
 * row's recorded file list (exact match) and the row is DONE. No path is ever
 * built from the URL alone.
 */
export function promoFilePath(r: Pick<PromoRender, "status" | "outputDir" | "files">, name: string): { path: string; file: PromoFileView } | null {
  if (r.status !== "DONE" || !r.outputDir || !/^[A-Za-z0-9_-]+\/[A-Za-z0-9_-]+$/.test(r.outputDir)) return null;
  const file = fileList(r.files).find((f) => f.name === name);
  return file ? { path: join(PROMO_RENDER_DIR, r.outputDir, file.name), file } : null;
}

/** Delete files of DONE renders past retention (rows stay, as EXPIRED). Returns how many expired. */
export async function sweepExpiredPromos(): Promise<number> {
  const old = await db.promoRender.findMany({
    where: { status: "DONE", finishedAt: { lt: new Date(Date.now() - PROMO_RETENTION_DAYS * DAY_MS) } },
    select: { id: true, outputDir: true },
  });
