// CREATOR PROMO VIDEOS — the render worker's PULL API, app side (2026-10-08).
//
// The render worker runs on node-2 (worker-render/promo-worker.ts) and must
// never hold production DB credentials, so instead of querying PromoRender it
// talks to these routes with a shared secret:
//
//   POST /api/promo/worker/claim                 → 200 { id, variables, formats, templateVersion } | 204 nothing to do
//   POST /api/promo/worker/<id>/progress          { step, progress }            (also the heartbeat)
//   PUT  /api/promo/worker/<id>/file/<name>?offset=N   one ≤ 8 MB chunk of one output file
//   POST /api/promo/worker/<id>/done              → files verified, HOW-TO-USE.txt written, DONE
//   POST /api/promo/worker/<id>/fail              { error }  → QUEUED again (1 retry) or FAILED
//
// Auth: header `x-promo-worker-secret` = PROMO_WORKER_SECRET (≥ 32 chars),
// compared in constant time. Unset/short secret → every route 404s (feature
// off). The secret is never logged or echoed.
//
// Uploads are CHUNKED on purpose: nginx caps request bodies at 20 MB and Next's
// middleware buffers at most 10 MB, while a finished 16:9 video is ~30–80 MB
// and the overlay end card ~650 MB. Each chunk must start exactly where the
// file on disk ends (a retried chunk may rewind to its own offset), every name
// must be one this render is expected to produce, and each kind has a size cap.

import { createHash, timingSafeEqual } from "node:crypto";
import { promises as fs } from "node:fs";
import { join } from "node:path";
import { db } from "@/lib/db";
import { howToUse } from "@/lib/promo-howto";
import { PROMO_RENDER_DIR, sweepExpiredPromos } from "@/lib/promo";
import {
  PROMO_CHUNK_BYTES,
  PROMO_GUIDE_FILE,
  PROMO_MAX_BYTES,
  expectedWorkerFiles,
  normalizeFormats,
  type PromoFileKind,
} from "@/lib/promo-core";

export const PROMO_WORKER_HEADER = "x-promo-worker-secret";
/** A RUNNING render with no heartbeat for this long is handed out again (or failed after its retry). */
const STALE_MS = Number(process.env.PROMO_STALE_MINUTES ?? 45) * 60_000;
/** On worker boot, a RUNNING render quiet for this long is its own previous life → back to QUEUED. */
const BOOT_STALE_MS = Number(process.env.PROMO_BOOT_STALE_MINUTES ?? 2) * 60_000;
const MAX_ATTEMPTS = 2;

const digest = (s: string) => createHash("sha256").update(s).digest();

/** True only for a request carrying the configured worker secret. */
export function isPromoWorker(req: Request): boolean {
  const secret = process.env.PROMO_WORKER_SECRET ?? "";
  if (secret.length < 32) return false;
  const got = req.headers.get(PROMO_WORKER_HEADER) ?? "";
  if (!got) return false;
  // Hash both sides: equal-length buffers, so timingSafeEqual never throws and length isn't leaked.
  return timingSafeEqual(digest(got), digest(secret));
}

export const notFound = () => new Response("Not found", { status: 404 });
export const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });

const ID_RE = /^[a-z0-9]{20,40}$/;
export const isRenderId = (id: string) => ID_RE.test(id);

const incomingDir = (id: string) => join(PROMO_RENDER_DIR, ".incoming", id);

/* ── stale work ────────────────────────────────────────────────────────── */

/** Requeue (or fail, once out of retries) RUNNING renders whose worker went quiet. */
export async function requeueStale(maxQuietMs: number): Promise<number> {
  const cutoff = new Date(Date.now() - maxQuietMs);
  const stale = await db.promoRender.findMany({
    where: { status: "RUNNING", OR: [{ heartbeatAt: { lt: cutoff } }, { heartbeatAt: null, startedAt: { lt: cutoff } }] },
    select: { id: true, attempts: true },
  });
  for (const r of stale) {
    const retry = r.attempts < MAX_ATTEMPTS;
    // Guarded on status so a render that just finished isn't flipped back.
    await db.promoRender.updateMany({
      where: { id: r.id, status: "RUNNING" },
      data: retry
        ? { status: "QUEUED", step: null, progress: 0 }
        : { status: "FAILED", step: null, error: "The render worker stopped responding.", finishedAt: new Date() },
    });
    await fs.rm(incomingDir(r.id), { recursive: true, force: true });
  }
  return stale.length;
}

let lastSweep = 0;
async function hourlySweep() {
  if (Date.now() - lastSweep < 3_600_000) return;
  lastSweep = Date.now();
  await sweepExpiredPromos().catch((e) => console.error("[promo] retention sweep failed:", e?.message ?? e));
}

/* ── claim ─────────────────────────────────────────────────────────────── */

export async function claimNext(opts: { boot: boolean; templateVersion: string }) {
  await requeueStale(opts.boot ? BOOT_STALE_MS : STALE_MS);
  await hourlySweep();
  for (let i = 0; i < 5; i++) {
    // Only work the worker's own template can render (its checkout carries PROMO_TEMPLATE_VERSION).
    const c = await db.promoRender.findFirst({
      where: { status: "QUEUED", templateVersion: opts.templateVersion },
      orderBy: { createdAt: "asc" },
    });
    if (!c) return null;
    // The atomic claim (same pattern as worker/index.ts): only one caller flips QUEUED → RUNNING.
    const now = new Date();
    const claim = await db.promoRender.updateMany({
      where: { id: c.id, status: "QUEUED" },
      data: { status: "RUNNING", attempts: { increment: 1 }, startedAt: now, heartbeatAt: now, error: null, progress: 0, step: "Starting" },
    });
    if (claim.count !== 1) continue;
    await fs.rm(incomingDir(c.id), { recursive: true, force: true });
    return { id: c.id, variables: c.vars, formats: normalizeFormats(c.formats), templateVersion: c.templateVersion };
  }
  return null;
}

/* ── progress ──────────────────────────────────────────────────────────── */

/** false when the render is no longer this worker's (requeued/failed/finished): the worker should abort it. */
export async function reportProgress(id: string, step: unknown, progress: unknown): Promise<boolean> {
  const p = Math.max(0, Math.min(99, Math.round(Number(progress) || 0)));
  const s = String(step ?? "").replace(/[\u0000-\u001f]/g, " ").slice(0, 120) || null;
  const r = await db.promoRender.updateMany({ where: { id, status: "RUNNING" }, data: { progress: p, step: s, heartbeatAt: new Date() } });
  return r.count === 1;
}

/* ── upload ────────────────────────────────────────────────────────────── */

type Running = { id: string; vars: unknown; formats: string };

async function runningRender(id: string): Promise<Running | null> {
  return db.promoRender.findFirst({ where: { id, status: "RUNNING" }, select: { id: true, vars: true, formats: true } });
}

function expectedFor(r: Running): { name: string; kind: PromoFileKind }[] {
  const v = (r.vars ?? {}) as { code?: string; lang?: string };
  try {
    return expectedWorkerFiles({ code: String(v.code ?? ""), lang: String(v.lang ?? "") }, r.formats.split(","));
  } catch {
    return [];
  }
}

