/** Append one chunk of `name` at `offset`. The name must be an expected output of this render. */
export async function writeChunk(id: string, name: string, offset: number, body: ReadableStream<Uint8Array> | null): Promise<ChunkResult> {
  const r = await runningRender(id);
  if (!r) return { ok: false, status: 409, error: "render is not running" };
  const want = expectedFor(r).find((f) => f.name === name);
  if (!want) return { ok: false, status: 404, error: "unexpected file name" };
