      }
      if (offset + written > PROMO_MAX_BYTES[want.kind]) {
        await reader.cancel().catch(() => {});
        await fh.truncate(offset);
        return { ok: false, status: 413, error: `${want.kind} file over the size cap` };
      }
      await fh.write(value, 0, value.length, offset + written - value.length);
    }
  } finally {
    await fh.close();
  }
