export async function finishRender(id: string): Promise<DoneResult> {
  const row = await db.promoRender.findFirst({ where: { id, status: "RUNNING" } });
  if (!row) return { ok: false, status: 409, error: "render is not running" };
  const expected = expectedFor(row);
