    {
      code: String(v.code ?? ""),
      url: String(v.url ?? ""),
      discountFirst: Number(v.discountFirst ?? 0),
      discountAfter: Number(v.discountAfter ?? 0),
    },
    files.map((f) => f.name),
  );
