  const final = join(PROMO_RENDER_DIR, rel);
  await fs.mkdir(join(PROMO_RENDER_DIR, row.partnerId), { recursive: true });
  await fs.rm(final, { recursive: true, force: true });
  await fs.rename(dir, final);
  const upd = await db.promoRender.updateMany({
    where: { id, status: "RUNNING" },
    data: { status: "DONE", progress: 100, step: "Done", outputDir: rel, files, finishedAt: new Date(), heartbeatAt: new Date(), error: null },
  });
  if (upd.count !== 1) {
    await fs.rm(final, { recursive: true, force: true });
    return { ok: false, status: 409, error: "render is not running" };
  }
  return { ok: true };
}

/** One failed attempt: retry once (back to QUEUED), then FAILED. */
export async function failRender(id: string, error: unknown): Promise<boolean> {
  const row = await db.promoRender.findFirst({ where: { id, status: "RUNNING" }, select: { attempts: true } });
  if (!row) return false;
  const retry = row.attempts < MAX_ATTEMPTS;
  const msg = String(error ?? "render failed").replace(/[\u0000-\u0008\u000b-\u001f]/g, " ").slice(0, 1500);
