    where: { id, status: "RUNNING" },
    data: retry
      ? { status: "QUEUED", error: msg, step: null, progress: 0 }
      : { status: "FAILED", error: msg, step: null, finishedAt: new Date() },
  });
  await fs.rm(incomingDir(id), { recursive: true, force: true });
  return true;
}

