// Serve one file from disk with single-Range support (bytes=a-b, a-, -n), so an
// in-page <video> can seek. Same semantics and response hardening as the
// creator media-kit route (app/api/creator-partner/kits/[code]/[file]) — the
// caller has already authorised the request and resolved `path` from a
// whitelist; this never builds a path itself.

import { createReadStream } from "node:fs";
import { Readable } from "node:stream";
import { NextResponse } from "next/server";

export function rangeFileResponse(
  req: Request,
  f: { path: string; size: number; name: string; contentType: string; mtime?: Date | null },
  opts: { download: boolean; head: boolean },
): NextResponse {
  const { size } = f;
  const safeName = f.name.replace(/[^A-Za-z0-9._-]/g, "_");
  const base: Record<string, string> = {
    "Content-Type": f.contentType,
    "Content-Disposition": `${opts.download ? "attachment" : "inline"}; filename="${safeName}"`,
    "Accept-Ranges": "bytes",
    "Cache-Control": "private, no-store",
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "default-src 'none'; sandbox",
  };
  if (f.mtime) base["Last-Modified"] = f.mtime.toUTCString();

  const range = req.headers.get("range");
  if (range) {
    const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
    // Multi-range or malformed: ignore the header and send the whole file (RFC 9110 allows it).
    if (m && (m[1] || m[2])) {
      let start: number;
      let end: number;
      if (!m[1]) {
        start = Math.max(0, size - Number(m[2]));
        end = size - 1;
      } else {
        start = Number(m[1]);
        end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
      }
      if (!Number.isSafeInteger(start) || start >= size || start > end) {
        return new NextResponse(null, { status: 416, headers: { ...base, "Content-Range": `bytes */${size}` } });
      }
      const headers = { ...base, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) };
      if (opts.head) return new NextResponse(null, { status: 206, headers });
      const stream = createReadStream(f.path, { start, end });
      return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, { status: 206, headers });
    }
  }
  const headers = { ...base, "Content-Length": String(size) };
  if (opts.head) return new NextResponse(null, { status: 200, headers });
  return new NextResponse(Readable.toWeb(createReadStream(f.path)) as unknown as ReadableStream, { status: 200, headers });
}

