import { NextRequest, NextResponse } from "next/server";
import { currentUser, impersonating } from "@/lib/auth";
import { db } from "@/lib/db";
import { PromoError, buildPromoVars, promoEnabled, promoGames, promoRenderView, promoStateFor, requestPromo } from "@/lib/promo";
import { isPromoLang, normalizeFormats } from "@/lib/promo-core";

export const dynamic = "force-dynamic";

/**
 * Creator promo videos for the SIGNED-IN partner (session cookie — not the
 * Kodely X-Api-Key surface under /api/partner/*).
 *   GET  → the card's state: offered games, last 10 renders, today's usage.
 *   POST { lang, family, handle?, formats[] } → queue (or reuse) a render.
 * Code, URL, prices and discounts are built from the DB (lib/promo.ts
 * buildPromoVars); the body only picks from allow-lists. 404 while the feature
 * is off (PROMO_WORKER_SECRET unset) or the user isn't a partner.
 */
async function partnerFor() {
  const user = await currentUser();
  if (!user) return { error: NextResponse.json({ error: "Sign in first." }, { status: 401 }) } as const;
