import { promises as fs } from "node:fs";
import { NextRequest, NextResponse } from "next/server";
import { currentUser, realUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { canAccess, isStaff } from "@/lib/rbac";
import { promoFilePath } from "@/lib/promo";
import { promoContentType } from "@/lib/promo-core";
import { rangeFileResponse } from "@/lib/range-file";

export const dynamic = "force-dynamic";

/**
 * One file of a finished creator promo render: /api/promo/<renderId>/file/<name>.
 * Same access model as the media-kit files (lib/partner-kit-access.ts): the
 * owning partner (currentUser — follows impersonation, so an admin
 * impersonating a partner sees exactly that partner's renders) or billing-area
 * staff (the REAL account); 401 signed out, 404 for everyone else — never 403,
 * so the URL space isn't advertised. `name` must be in the row's recorded file
 * list (lib/promo.ts promoFilePath): no path is built from the URL. 410 once
 * the retention sweep has removed it. Range-capable; `?download=1` = attachment.
 */
async function serve(req: NextRequest, params: Promise<{ id: string; name: string }>, head: boolean) {
  const { id, name } = await params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "Sign in first." }, { status: 401 });
  const r = await db.promoRender.findUnique({
    where: { id },
    select: { status: true, outputDir: true, files: true, partner: { select: { userId: true } } },
  });
  if (!r) return NextResponse.json({ error: "Not found" }, { status: 404 });
  const real = await realUser();
  const staff = !!real && isStaff(real.role) && canAccess(real.role, "billing");
  if (!staff && r.partner.userId !== user.id) return NextResponse.json({ error: "Not found" }, { status: 404 });
  if (r.status === "EXPIRED") return NextResponse.json({ error: "This video has expired. Generate it again." }, { status: 410 });
  const hit = promoFilePath(r, name);
  if (!hit) return NextResponse.json({ error: "Not found" }, { status: 404 });
  const st = await fs.lstat(hit.path).catch(() => null);
  if (!st || !st.isFile()) return NextResponse.json({ error: "This video has expired. Generate it again." }, { status: 410 });
  return rangeFileResponse(
    req,
    { path: hit.path, size: st.size, name: hit.file.name, contentType: promoContentType(hit.file.name), mtime: st.mtime },
    { download: req.nextUrl.searchParams.get("download") === "1", head },
  );
}

export function GET(req: NextRequest, { params }: { params: Promise<{ id: string; name: string }> }) {
  return serve(req, params, false);
}

export function HEAD(req: NextRequest, { params }: { params: Promise<{ id: string; name: string }> }) {
  return serve(req, params, true);
}

