import { claimNext, isPromoWorker, json, notFound } from "@/lib/promo-worker";

export const dynamic = "force-dynamic";

/**
 * Render worker (node-2): claim the oldest QUEUED render for the worker's
 * template version. Body `{ templateVersion, boot? }` — `boot: true` during the
 * worker's first minutes after a (re)start also requeues RUNNING renders that
 * went quiet (its own previous life). 200 `{ id, variables, formats,
 * templateVersion }`, or 204 when there is nothing to do. See lib/promo-worker.ts.
 */
export async function POST(req: Request) {
  if (!isPromoWorker(req)) return notFound();
  let body: Record<string, unknown> = {};
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    /* empty body is fine */
  }
  const templateVersion = typeof body.templateVersion === "string" ? body.templateVersion.slice(0, 32) : "";
  if (!templateVersion) return json({ error: "templateVersion required" }, 400);
  const job = await claimNext({ boot: body.boot === true, templateVersion });
  if (!job) return new Response(null, { status: 204, headers: { "cache-control": "no-store" } });
  return json(job);
}
EOF
