import { isPromoWorker, isRenderId, json, notFound, reportProgress } from "@/lib/promo-worker";

export const dynamic = "force-dynamic";

/** Render worker: `{ step, progress }` for a RUNNING render (doubles as its heartbeat). 409 = no longer yours, abort it. */
export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  if (!isPromoWorker(req)) return notFound();
  const { id } = await params;
  if (!isRenderId(id)) return notFound();
  let body: Record<string, unknown> = {};
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    return json({ error: "bad json" }, 400);
  }
  const ok = await reportProgress(id, body.step, body.progress);
  return ok ? json({ ok: true }) : json({ error: "render is not running" }, 409);
}
