import { isPromoWorker, isRenderId, json, notFound, writeChunk } from "@/lib/promo-worker";

export const dynamic = "force-dynamic";

/**
 * Render worker: upload ONE chunk (≤ 8 MB) of one output file.
 * PUT /api/promo/worker/<id>/file/<name>?offset=<bytes already sent>
 * The name must be one this render is expected to produce, the offset must be
 * the current end of the file (or an earlier offset, to retry a chunk), and
 * each kind has a total size cap. 200 `{ size }` = bytes on disk now. See
 * lib/promo-worker.ts writeChunk.
 */
export async function PUT(req: Request, { params }: { params: Promise<{ id: string; name: string }> }) {
  if (!isPromoWorker(req)) return notFound();
  const { id, name } = await params;
  if (!isRenderId(id)) return notFound();
  const offset = Number(new URL(req.url).searchParams.get("offset") ?? "0");
  const r = await writeChunk(id, name, offset, req.body);
  if (!r.ok) return json({ error: r.error, size: r.size }, r.status);
  return json({ size: r.size });
}
