// CREATOR PROMO VIDEOS — the render worker (2026-10-08). Runs on NODE-2, never
// on the primary (which serves the live site + customer VMs and hard-crashed
// from CPU load on 2026-10-06).
//
// It holds NO database credentials. It pulls work from the app over HTTPS with
// a shared secret (lib/promo-worker.ts documents the API), renders with the
// HyperFrames CLI + headless Chrome + ffmpeg, and uploads the files back in
// ≤ 8 MB chunks. The app writes HOW-TO-USE.txt and marks the render DONE.
//
// Plain `node` runs this file directly (Node ≥ 22.18 strips the types), so it
// imports nothing but node: builtins and the pure lib/promo-core.ts. No npm
// install of the app is needed where it runs.
//
// Every render task is wrapped in `flock` on node-2's build lock, so a render
// never competes with a release build: it waits for a running build, and a
// build waits at most one task (≈ 5 min) for a render.
//
// Env (see docs/DOCUMENTATION.md "Creator promo videos" for the systemd unit):
//   PROMO_API_URL          app base URL, e.g. https://nxeon.cloud           (required)
//   PROMO_WORKER_SECRET    shared secret, same value as the app's .env      (required, ≥ 32 chars)
//   PROMO_TEMPLATE_DIR     video-templates/creator-promo of THIS checkout   (default: ../video-templates/creator-promo)
//   PROMO_WORK_DIR         scratch dir for renders                          (default: /tank/nxeon-render/work)
//   HYPERFRAMES_BIN        path to hyperframes/bin/hyperframes.mjs           (required)
//   HYPERFRAMES_BROWSER_PATH, HYPERFRAMES_FFMPEG_PATH, HYPERFRAMES_FFPROBE_PATH   read by HyperFrames itself
//   PROMO_FFMPEG           ffmpeg for end frames (default: $HYPERFRAMES_FFMPEG_PATH or "ffmpeg")
//   PROMO_BUILD_LOCK       lock file to share with release builds (default /run/lock/nxeon-build.lock; "" = none)
//   PROMO_LOCK_WAIT_SEC    max wait for the lock per task (default 3600)
//   PROMO_WORKERS          HyperFrames Chrome workers per render (default 2)
//   PROMO_TIMEOUT_MS       hard cap per render task (default 30 min)
//   PROMO_ONCE=1           exit after one render (or when the queue is empty) — for tests

import { spawn } from "node:child_process";
import { createReadStream, promises as fs } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { PROMO_CHUNK_BYTES, PROMO_TEMPLATE_VERSION, promoTasks, type PromoTask } from "../lib/promo-core.ts";

const HERE = dirname(fileURLToPath(import.meta.url));
const env = process.env;
const API = (env.PROMO_API_URL ?? "").replace(/\/+$/, "");
const SECRET = env.PROMO_WORKER_SECRET ?? "";
const TPL = env.PROMO_TEMPLATE_DIR ?? join(HERE, "..", "video-templates", "creator-promo");
const WORK = env.PROMO_WORK_DIR ?? "/tank/nxeon-render/work";
const HF = env.HYPERFRAMES_BIN ?? "";
