"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import {
  PROMO_FORMAT_LABELS,
  PROMO_LANGS,
  PROMO_MAX_HANDLE,
  promoFileUrl,
  type PromoFormat,
  type PromoRenderView,
  type PromoState,
} from "@/lib/promo-core";

/* "Make your own version" — the creator promo video generator on the partner
   portal's Media kit tab, under the owner-made sponsored segment
   (PartnerMediaKit.tsx, whose styling this shares). The partner picks a
   language, a game, an optional on-screen handle and the formats; the code,
   partner link, prices and discount in the video all come from the server
   (lib/promo.ts). Initial state is server-rendered (app/dashboard/partner/
   page.tsx); GET /api/promo is polled every 3 s only while a render is
   queued or running. */

const INPUT =
  "h-[42px] w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3.5 text-[13.5px] " +
  "text-white outline-none transition placeholder:text-tx-faint focus:border-brand-400/70";

const FORMAT_HINT: Record<PromoFormat, string> = {
  "16x9": "1080p60 MP4 for YouTube and Twitch",
  "9x16": "Vertical MP4 for Shorts, TikTok and Reels",
  overlays: "Transparent ProRes overlays (large files, about 1 GB)",
};

const ACTIVE = (r: PromoRenderView) => r.status === "QUEUED" || r.status === "RUNNING";

export function PartnerPromoVideos({ initial }: { initial: PromoState }) {
  const [state, setState] = useState<PromoState>(initial);
  const [lang, setLang] = useState<string>("en");
  const [family, setFamily] = useState<string>(initial.games[0]?.family ?? "");
  const [handle, setHandle] = useState("");
  const [formats, setFormats] = useState<PromoFormat[]>(["16x9"]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const alive = useRef(true);
  useEffect(() => () => { alive.current = false; }, []);

  const refresh = useCallback(async () => {
    try {
      const r = await fetch("/api/promo", { cache: "no-store" });
      if (r.ok && alive.current) setState((await r.json()) as PromoState);
    } catch {
      /* offline for a moment — the next poll retries */
    }
  }, []);

  const anyActive = state.renders.some(ACTIVE);
  useEffect(() => {
    if (!anyActive) return;
    const t = setInterval(refresh, 3000);
    return () => clearInterval(t);
  }, [anyActive, refresh]);

  const full = state.usedToday >= state.maxPerDay;
  const left = Math.max(0, state.maxPerDay - state.usedToday);
  const noGames = state.games.length === 0;

  const toggle = (f: PromoFormat) =>
    setFormats((cur) => (cur.includes(f) ? cur.filter((x) => x !== f) : [...cur, f]));

  async function generate(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setNotice(null);
    if (formats.length === 0) return setError("Pick at least one format.");
    setBusy(true);
    try {
      const r = await fetch("/api/promo", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ lang, family, handle, formats }),
      });
      const body = (await r.json().catch(() => ({}))) as { error?: string; reused?: boolean };
      if (!r.ok) setError(body.error ?? "Couldn't queue the video. Please try again.");
      else if (body.reused) setNotice("You already have this exact video, so we kept that one. It's in the list below.");
      await refresh();
    } catch {
      setError("Couldn't reach Nxeon. Check your connection and try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Panel
      title="Make your own version"
      sub={`Generate the sponsored segment with your code ${state.code} on screen, in your language and for your game. The prices and offer in it are the live ones.`}
    >
      <form onSubmit={generate} className="flex min-w-0 flex-col gap-4">
        <div className="grid min-w-0 gap-3 sm:grid-cols-2 xl:grid-cols-3">
          <Field label="Language" hint="On-screen text. The recreated dashboard stays English.">
            <select value={lang} onChange={(e) => setLang(e.target.value)} className={INPUT} disabled={full}>
              {Object.entries(PROMO_LANGS).map(([k, label]) => (
                <option key={k} value={k}>{label}</option>
              ))}
            </select>
          </Field>
          <Field label="Game" hint="Shown in the game pick, order summary and end card.">
            <select value={family} onChange={(e) => setFamily(e.target.value)} className={INPUT} disabled={full || noGames}>
              {state.games.map((g) => (
                <option key={g.family} value={g.family}>{g.name}</option>
              ))}
            </select>
          </Field>
          <Field label="Your handle (optional)" hint={`Shows "with @handle" on the end card.`}>
            <input
              value={handle}
              onChange={(e) => setHandle(e.target.value.replace(/[^A-Za-z0-9_.@-]/g, "").slice(0, PROMO_MAX_HANDLE + 1))}
              placeholder="@yourchannel"
              maxLength={PROMO_MAX_HANDLE + 1}
              className={INPUT}
              disabled={full}
            />
          </Field>
        </div>

        <fieldset className="flex min-w-0 flex-col gap-2">
          <legend className="mb-1.5 text-[11px] font-bold uppercase tracking-[0.1em] text-tx-faint">Formats</legend>
          <div className="grid min-w-0 gap-2 sm:grid-cols-3">
            {(Object.keys(PROMO_FORMAT_LABELS) as PromoFormat[]).map((f) => {
              const on = formats.includes(f);
              return (
                <label
                  key={f}
                  className={
                    "flex min-w-0 cursor-pointer items-start gap-2.5 rounded-[11px] border px-3 py-2.5 transition " +
                    (on ? "border-[#8b5cff]/70 bg-[rgba(80,40,190,.22)]" : "border-rim-soft hover:border-rim-hi") +
                    (full ? " pointer-events-none opacity-60" : "")
                  }
                >
                  <input type="checkbox" checked={on} onChange={() => toggle(f)} disabled={full} className="mt-[3px] accent-[#8b5cff]" />
                  <span className="flex min-w-0 flex-col">
                    <span className="text-[12.5px] font-bold text-white">{f === "overlays" ? "Overlay kit" : PROMO_FORMAT_LABELS[f]}</span>
                    <span className="text-[11px] leading-snug text-tx-faint">{FORMAT_HINT[f]}</span>
                  </span>
                </label>
              );
            })}
          </div>
        </fieldset>

        {full ? (
          <div role="status" className="flex items-start gap-2.5 rounded-[12px] border border-[rgba(255,184,77,0.35)] bg-[rgba(255,184,77,0.08)] px-3.5 py-2.5">
            <Icon name="clock" size={15} tone="amber" className="mt-[1px] flex-none" />
            <span className="text-[12.5px] leading-relaxed text-tx-dim">
              You&apos;ve made {state.maxPerDay} videos in the last 24 hours, which is the daily limit.
              {state.nextSlotAt && (
                <>
                  {" "}You can make another <b className="text-white" suppressHydrationWarning>{fmtRelative(state.nextSlotAt)}</b>.
                </>
              )}{" "}
              Your finished videos below are still there to download.
            </span>
          </div>
        ) : noGames ? (
          <p className="text-[12.5px] text-tx-mute">No game can be priced for a video right now. Please check back soon.</p>
        ) : null}

        <div className="flex flex-wrap items-center gap-3">
          <button type="submit" disabled={busy || full || noGames || formats.length === 0} className="nx-cta gap-2 px-5 py-2.5 text-[13px] disabled:opacity-60">
            <Icon name="video" size={14} tone="inherit" /> {busy ? "Queueing…" : "Generate video"}
          </button>
          <span className="text-[11.5px] text-tx-faint">
            {full ? "Daily limit reached" : `${left} of ${state.maxPerDay} left today`} · files are kept {state.retentionDays} days
          </span>
        </div>
        {error && <p role="alert" className="rounded-[9px] border border-red-500/35 bg-red-500/10 px-3 py-2 text-[12.5px] text-red-300">{error}</p>}
        {notice && <p role="status" className="text-[12.5px] font-semibold text-emerald-400">{notice}</p>}
        <p className="text-[11.5px] leading-relaxed text-tx-faint">
          Takes a few minutes. Tick YouTube&apos;s &ldquo;Includes paid promotion&rdquo; box. Have a native speaker check translated overlays before publishing.
        </p>
      </form>

      {state.renders.length > 0 && (
        <div className="mt-4 flex min-w-0 flex-col gap-3 border-t border-rim-soft pt-4">
          <span className="text-[12px] font-bold uppercase tracking-[0.1em] text-tx-faint">Your generated videos</span>
          <div className="grid min-w-0 gap-3 md:grid-cols-2">
            {state.renders.map((r) => (
              <RenderCard key={r.id} r={r} />
            ))}
          </div>
        </div>
      )}
    </Panel>
  );
}

function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) {
  return (
    <label className="flex min-w-0 flex-col gap-1.5">
      <span className="text-[11px] font-bold uppercase tracking-[0.1em] text-tx-faint">{label}</span>
      {children}
      {hint && <span className="text-[11px] text-tx-faint">{hint}</span>}
    </label>
  );
}

const STATUS: Record<PromoRenderView["status"], { label: string; chip: string }> = {
  QUEUED: { label: "Queued", chip: "chip-slate" },
  RUNNING: { label: "Rendering", chip: "chip-blue" },
  DONE: { label: "Ready", chip: "chip-mint" },
  FAILED: { label: "Failed", chip: "chip-rose" },
  EXPIRED: { label: "Expired", chip: "chip-slate" },
};

function RenderCard({ r }: { r: PromoRenderView }) {
  const s = STATUS[r.status];
  const video = r.files.find((f) => f.kind === "video");
  const poster = video ? r.files.find((f) => f.name === video.name.replace(/\.mp4$/, "_endframe.png")) : null;
  const title = `${r.gameName} · ${r.lang}`;
  return (
    <div className="flex min-w-0 flex-col overflow-hidden rounded-[12px] border border-rim-soft bg-well">
      {r.status === "DONE" && video ? (
        <div className="nx-dark-island relative aspect-video w-full bg-[#03060f]">
          <video
            controls
            preload="metadata"
            playsInline
            poster={poster ? promoFileUrl(r.id, poster.name) : undefined}
            className="absolute inset-0 h-full w-full bg-[#03060f] object-contain"
            aria-label={`Generated promo video, ${title}`}
          >
            <source src={promoFileUrl(r.id, video.name)} type="video/mp4" />
          </video>
        </div>
      ) : (
        <div className="nx-dark-island relative grid aspect-video w-full place-items-center bg-[radial-gradient(70%_90%_at_50%_40%,rgba(80,40,190,.28),#03060f_72%)]">
          <span className="flex flex-col items-center gap-2 px-6 text-center">
            <Icon name={r.status === "FAILED" ? "alert" : r.status === "EXPIRED" ? "clock" : "video"} size={26} tone={r.status === "FAILED" ? "rose" : "cyan"} />
            <span className="text-[12.5px] font-semibold text-white">
              {r.status === "QUEUED" ? "Waiting for a render slot" : r.status === "RUNNING" ? r.step ?? "Rendering" : r.status === "FAILED" ? "This render didn't finish" : "Files removed after the retention period"}
            </span>
          </span>
        </div>
      )}
      <div className="flex flex-col gap-2.5 border-t border-rim-soft px-3.5 py-3">
        <div className="flex flex-wrap items-center gap-2">
          <span className="min-w-0 truncate text-[13.5px] font-extrabold tracking-[-0.01em] text-white">{title}</span>
          {r.formats.map((f) => (
            <span key={f} className="chip-tone chip-blue">{f === "overlays" ? "Overlays" : f.replace("x", ":")}</span>
          ))}
          <span className={"chip-tone ml-auto " + s.chip}>{s.label}</span>
        </div>
        {r.handle && <span className="text-[11.5px] text-tx-faint">with @{r.handle}</span>}

        {ACTIVE(r) && (
          <div className="flex flex-col gap-1.5" aria-live="polite">
            <div className="h-[8px] w-full overflow-hidden rounded-full bg-[rgba(255,255,255,0.06)]" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={r.progress} aria-label="Render progress">
              <div className="h-full rounded-full bg-[linear-gradient(90deg,#3b6be8,#7b3fef)] transition-[width] duration-700" style={{ width: `${Math.max(r.status === "RUNNING" ? 3 : 0, r.progress)}%` }} />
            </div>
            <span className="flex justify-between text-[11px] text-tx-faint">
              <span>{r.status === "QUEUED" ? "Queued — it starts as soon as a slot is free" : r.step ?? "Rendering"}</span>
              <span className="mono">{r.progress}%</span>
            </span>
          </div>
        )}

        {r.status === "FAILED" && r.error && <span className="text-[12px] text-tx-mute">{r.error}</span>}

        {r.status === "DONE" && r.files.length > 0 && (
          <ul className="flex flex-col gap-1.5 border-t border-rim-soft pt-2.5">
            {r.files.map((f) => (
              <li key={f.name} className="flex min-w-0 items-center gap-2 text-[11.5px]">
                <Icon name={f.kind === "video" || f.kind === "overlay" ? "video" : f.kind === "text" ? "file" : "eye"} size={12} className="flex-none" />
                <a href={promoFileUrl(r.id, f.name, true)} className="mono min-w-0 flex-1 truncate text-tx-dim hover:text-white">{f.name}</a>
                <span className="flex-none text-tx-faint">{fmtSize(f.bytes)}</span>
                <a href={promoFileUrl(r.id, f.name, true)} aria-label={`Download ${f.name}`} className="flex-none text-cyan hover:text-white">
                  <Icon name="download" size={13} tone="inherit" />
                </a>
              </li>
            ))}
          </ul>
        )}
        <span className="text-[11px] text-tx-faint" suppressHydrationWarning>
          {r.status === "DONE" && r.expiresAt ? `Ready · kept until ${fmtDay(r.expiresAt)}` : `Requested ${fmtRelative(r.createdAt)}`}
        </span>
      </div>
    </div>
  );
}

function fmtSize(n: number): string {
  if (n >= 1024 * 1024 * 1024) return `${(n / 1024 / 1024 / 1024).toFixed(2)} GB`;
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
  return `${n} B`;
}

function fmtDay(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

/** "in 3 h", "in 12 min", "5 min ago", "2 d ago". */
function fmtRelative(iso: string): string {
  const d = new Date(iso).getTime() - Date.now();
  const a = Math.abs(d);
  const v = a < 3_600_000 ? `${Math.max(1, Math.round(a / 60_000))} min` : a < 86_400_000 ? `${Math.round(a / 3_600_000)} h` : `${Math.round(a / 86_400_000)} d`;
  return d > 0 ? `in ${v}` : `${v} ago`;
}

