"use server";

// Admin: batch-queue creator promo videos for several partners at once
// (outreach use — e.g. render a personalised segment before inviting a
// creator). Billing-area gated like every other partner admin action
// (lib/actions-partner.ts), refused while impersonating, and the same
// lib/promo.ts path the partner card uses — so the video's code, link, prices
// and discount always come from the DB. Bypasses the per-partner daily limit;
// identical requests still reuse an existing render.

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { assertNotImpersonating } from "./auth";
import { PromoError, buildPromoVars, promoEnabled, promoGames, requestPromo } from "./promo";
import { isPromoLang, normalizeFormats, promoCode } from "./promo-core";

export type PromoBatchResult = { ok?: boolean; error?: string; queued?: number; reused?: number; skipped?: string[] };

export async function adminQueuePromoBatch(_prev: unknown, formData: FormData): Promise<PromoBatchResult> {
  const admin = await requireArea("billing");
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: (e as Error).message };
  }
  if (!promoEnabled()) return { error: "Promo videos are off (PROMO_WORKER_SECRET is not set)." };

  const partnerIds = [...new Set(formData.getAll("partnerId").map(String))].slice(0, 100);
  const langs = [...new Set(formData.getAll("lang").map(String))].filter(isPromoLang);
  const family = String(formData.get("family") ?? "");
  const formats = normalizeFormats(formData.getAll("format").map(String));
  const handleFromProfile = formData.get("handleFromProfile") === "1";
  if (partnerIds.length === 0) return { error: "Tick at least one partner." };
  if (langs.length === 0) return { error: "Tick at least one language." };
  if (formats.length === 0) return { error: "Tick at least one format." };
  if (!(await promoGames()).some((g) => g.family === family)) return { error: "That game can't be priced for a video right now." };

  const partners = await db.referralPartner.findMany({
    where: { id: { in: partnerIds } },
    select: { id: true, name: true, code: true, payoutProfile: { select: { social: true } } },
  });
  let queued = 0;
  let reused = 0;
  const skipped: string[] = [];
  for (const p of partners) {
    if (!promoCode(p.code)) {
      skipped.push(`${p.name} (code ${p.code} can't be shown in a video)`);
      continue;
    }
    // An @handle from the partner's own Settings, when it is one (not a URL).
    const social = (p.payoutProfile?.social ?? "").trim();
    const handle = handleFromProfile && /^@?[A-Za-z0-9_.-]{2,30}$/.test(social) ? social : "";
    for (const lang of langs) {
      try {
        const vars = await buildPromoVars(p, { lang, family, handle });
        const r = await requestPromo(p.id, admin.id, vars, formats, { bypassLimit: true });
        if (r.reused) reused++;
        else queued++;
      } catch (e) {
        skipped.push(`${p.name} · ${lang}: ${e instanceof PromoError ? e.message : "failed to queue"}`);
      }
    }
  }
  revalidatePath("/admin/partners");
  for (const p of partners) revalidatePath(`/admin/partners/${p.id}`);
  return { ok: true, queued, reused, skipped };
}

