"use client";

import { useActionState, useMemo, useState } from "react";
import { adminQueuePromoBatch, type PromoBatchResult } from "@/lib/actions-promo";
import { PROMO_FORMAT_LABELS, PROMO_LANGS, type PromoFormat, type PromoGameOption } from "@/lib/promo-core";

/* Admin › Partners › "Render promo videos": pick partners, languages, a game
   and formats, and queue one creator promo render per partner × language
   (lib/actions-promo.ts). Renders run on node-2; progress and files show on
   each partner's admin page and in their own Media kit tab. */

export type PromoBatchPartner = { id: string; name: string; code: string; status: string; renderable: boolean };

export function PromoBatchForm({ partners, games }: { partners: PromoBatchPartner[]; games: PromoGameOption[] }) {
  const [state, action, pending] = useActionState<PromoBatchResult, FormData>(adminQueuePromoBatch, {});
  const [picked, setPicked] = useState<Set<string>>(new Set());
  const [q, setQ] = useState("");
  const shown = useMemo(() => {
    const s = q.trim().toLowerCase();
    return s ? partners.filter((p) => p.name.toLowerCase().includes(s) || p.code.toLowerCase().includes(s)) : partners;
  }, [partners, q]);
  const toggle = (id: string) =>
    setPicked((cur) => {
      const n = new Set(cur);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });

  if (games.length === 0) {
    return <p className="text-sm text-slate-400">No game can be priced for a video right now (each needs active monthly 2, 4 and 8 GB plans).</p>;
  }

  return (
    <form action={action} className="space-y-4">
      {state.error && <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>}
      {state.ok && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Queued {state.queued} render{state.queued === 1 ? "" : "s"}
