          {shown.length === 0 && <p className="px-2 py-3 text-xs text-slate-500">No partners match.</p>}
          {shown.map((p) => (
            <label key={p.id} className={`flex items-center gap-3 rounded-md px-2 py-1.5 text-sm ${p.renderable ? "cursor-pointer hover:bg-white/[0.04]" : "opacity-50"}`}>
              <input
                type="checkbox"
                name="partnerId"
                value={p.id}
                checked={picked.has(p.id)}
                onChange={() => toggle(p.id)}
                disabled={!p.renderable}
              />
              <span className="min-w-0 flex-1 truncate text-slate-200">{p.name}</span>
