              {p.status !== "ACTIVE" && <span className="text-xs text-slate-500">{p.status.toLowerCase()}</span>}
              {!p.renderable && <span className="text-xs text-amber-400">code can&apos;t be shown</span>}
            </label>
          ))}
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-3">
        <fieldset>
          <legend className="label">Languages</legend>
          <div className="mt-1 space-y-1">
            {Object.entries(PROMO_LANGS).map(([k, label]) => (
              <label key={k} className="flex items-center gap-2 text-sm text-slate-300">
