      <div className="card space-y-4">
        <div>
          <p className="section-label">Free game servers</p>
        )}
      </div>
    </div>
  );
}

function KitFileTable({ code, files, empty }: { code: string; files: KitFile[]; empty: string }) {
  if (files.length === 0) return <p className="text-sm text-slate-500">{empty}</p>;
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="text-left text-xs text-slate-500">
            <th className="py-1.5 pr-3 font-medium">File</th>
            <th className="py-1.5 pr-3 text-right font-medium">Size</th>
            <th className="py-1.5 pr-3 font-medium">Updated</th>
            <th className="py-1.5 font-medium" />
          </tr>
        </thead>
        <tbody>
          {files.map((f) => (
            <tr key={f.name} className="border-t border-white/5">
              <td className="py-1.5 pr-3 font-mono text-xs text-slate-200 break-all">{f.name}</td>
              <td className="py-1.5 pr-3 text-right text-xs text-slate-400 whitespace-nowrap">
                {f.sizeBytes >= 1048576 ? `${(f.sizeBytes / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(f.sizeBytes / 1024))} KB`}
              </td>
              <td className="py-1.5 pr-3 text-xs text-slate-500 whitespace-nowrap">{timeAgo(new Date(f.updatedAt))}</td>
              <td className="py-1.5 text-right text-xs whitespace-nowrap">
                <a href={kitFileUrl(code, f.name)} target="_blank" rel="noreferrer" className="text-brand-300 hover:underline">Preview</a>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

