import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import {
  PROMO_TEMPLATE_VERSION,
  cleanPromoHandle,
  expectedWorkerFiles,
  normalizeFormats,
  pickPromoTiers,
  promoCacheMaterial,
  promoCode,
  promoPricingFromTiers,
  promoTasks,
  promoUsd,
  type PromoPlanRow,
} from "../lib/promo-core.ts";
import { howToUse } from "../lib/promo-howto.ts";
import { parseKitGuide } from "../lib/partner-kits.ts";
import { partnerDiscountCentsFor } from "../lib/partner-discount.ts";

const plan = (ramMB: number, priceCents: number, extra: Partial<PromoPlanRow> = {}): PromoPlanRow => ({
  ramMB, cpuCores: ramMB >= 8192 ? 3 : 2, diskGB: ramMB / 1024 * 10, priceCents, termMonths: 1, ...extra,
});
const key = (vars: Record<string, unknown>, fmts: string[], v?: string) =>
  createHash("sha256").update(promoCacheMaterial(vars, fmts, v)).digest("hex");

test("promoCode: the template's own charset, 2–16 chars, upper-cased", () => {
  assert.equal(promoCode(" hoven "), "HOVEN");
  assert.equal(promoCode("A_B-9"), "A_B-9");
  assert.equal(promoCode("X"), null);
  assert.equal(promoCode("WAY_TOO_LONG_CODE_X"), null);
  assert.equal(promoCode("BAD CODE"), null);
  assert.equal(promoCode("ÜBER"), null);
});

test("cleanPromoHandle strips @ and anything unsafe, max 30", () => {
  assert.equal(cleanPromoHandle("@@ArmyOfZeus"), "ArmyOfZeus");
  assert.equal(cleanPromoHandle("<script>x"), "scriptx");
  assert.equal(cleanPromoHandle("a".repeat(40)).length, 30);
  assert.equal(cleanPromoHandle(undefined), "");
});

test("pickPromoTiers needs monthly 2, 4 and 8 GB tiers; cheapest wins", () => {
  assert.equal(pickPromoTiers([plan(2048, 718), plan(4096, 1294)]), null, "no 8 GB tier → hidden");
  assert.equal(pickPromoTiers([plan(2048, 718), plan(4096, 1294), plan(8192, 2302, { termMonths: 12 })]), null, "annual-only 8 GB doesn't count");
  const t = pickPromoTiers([plan(2048, 900), plan(2048, 718), plan(4096, 1294), plan(8192, 2302), plan(1024, 300)]);
  assert.ok(t);
  assert.equal(t.t2.priceCents, 718);
});

test("promoPricingFromTiers reproduces the recording's Minecraft numbers and the real discount rounding", () => {
  const t = pickPromoTiers([plan(2048, 718, { introPriceCents: 499, diskGB: 20 }), plan(4096, 1294, { diskGB: 30 }), plan(8192, 2302, { diskGB: 50 })])!;
  const p = promoPricingFromTiers(t, 50, (x) => ({ 2048: 9, 4096: 20, 8192: 50 })[x.ramMB] ?? null);
  assert.equal(p.priceBefore, "$4.99");
  // Same rounding as the checkout: 499 − round(249.5) = 249.
  assert.equal(p.priceAfter, promoUsd(499 - partnerDiscountCentsFor(499, 50)));
  assert.equal(p.priceAfter, "$2.49");
  assert.equal(p.renewPrice, "$7.18");
  assert.equal(p.upgradeRenew, "$12.94");
  assert.equal(p.tier8Price, "$23.02");
  assert.equal(p.upgradePrice, "$4.03"); // 70% of (12.94 − 7.18)
  assert.deepEqual([p.tierCpu2, p.tierDisk2, p.tierPlayers2, p.tierCpu8, p.tierDisk8, p.tierPlayers8], [2, 20, 9, 3, 50, 50]);
});

test("no intro price → first month is the regular price; an intro >= regular is ignored", () => {
  const t = pickPromoTiers([plan(2048, 934, { introPriceCents: 934 }), plan(4096, 1500), plan(8192, 2600)])!;
  const p = promoPricingFromTiers(t, 50, () => null);
  assert.equal(p.priceBefore, "$9.34");
  assert.equal(p.priceAfter, "$4.67");
  assert.equal(p.tierPlayers2, 0, "unknown players → hidden in the video");
});

test("cache key: same input → same key, order-independent; version bump or any change → new key", () => {
  const a = key({ code: "TEST42", lang: "es", game: "valheim" }, ["16x9"]);
  assert.equal(a, key({ game: "valheim", lang: "es", code: "TEST42" }, ["16x9", "16x9"]));
  assert.notEqual(a, key({ code: "TEST42", lang: "es", game: "valheim" }, ["16x9"], PROMO_TEMPLATE_VERSION + "-next"));
  assert.notEqual(a, key({ code: "TEST42", lang: "en", game: "valheim" }, ["16x9"]));
  assert.notEqual(a, key({ code: "TEST42", lang: "es", game: "valheim" }, ["16x9", "9x16"]));
  assert.equal(key({ x: 1 }, ["9x16", "16x9"]), key({ x: 1 }, ["16x9", "9x16"]));
});

test("normalizeFormats keeps only known formats in render order", () => {
  assert.deepEqual(normalizeFormats(["overlays", "16x9", "nope", "16x9"]), ["16x9", "overlays"]);
  assert.deepEqual(normalizeFormats("9x16,16x9"), ["16x9", "9x16"]);
  assert.deepEqual(normalizeFormats(null), []);
});

test("promoTasks + expectedWorkerFiles: media-kit file names, whitelist only", () => {
  const tasks = promoTasks({ code: "test42", lang: "es" }, ["16x9", "overlays"]);
  assert.deepEqual(tasks.map((t) => t.out), [
    "nxeon-promo_TEST42_es_16x9.mp4",
    "nxeon-overlay_sting_TEST42.mov",
    "nxeon-overlay_code_TEST42.mov",
    "nxeon-overlay_endcard_TEST42.mov",
  ]);
  assert.ok(tasks[0].args.includes("60") && tasks[0].args.includes("high"));
  const files = expectedWorkerFiles({ code: "TEST42", lang: "es" }, ["9x16"]);
  assert.deepEqual(files, [
    { name: "nxeon-promo_TEST42_es_9x16.mp4", kind: "video" },
    { name: "nxeon-promo_TEST42_es_9x16_endframe.png", kind: "image" },
  ]);
  assert.ok(!files.some((f) => f.name.includes("..") || f.name.includes("/")));
  assert.throws(() => promoTasks({ code: "../x", lang: "es" }, ["16x9"]));
  assert.throws(() => promoTasks({ code: "TEST42", lang: "fr" }, ["16x9"]));
});

test("HOW-TO-USE.txt carries the real code/url/discounts and parses with the media-kit guide parser", () => {
  const txt = howToUse({ code: "TEST42", url: "nxeon.cloud/partner/TEST42", discountFirst: 50, discountAfter: 10 }, ["a.mp4", "a_endframe.png"]);
  assert.match(txt, /use my code TEST42: that's 50% off/);
  assert.match(txt, /https:\/\/nxeon\.cloud\/partner\/TEST42/);
  const g = parseKitGuide(txt);
  assert.equal(g.title, "NXEON SPONSORED SEGMENT · code TEST42");
  assert.deepEqual(g.files, ["a.mp4", "a_endframe.png"]);
  assert.ok(g.steps.length >= 4);
  assert.ok(g.narration.length >= 10);
  assert.match(g.description ?? "", /10% off for life/);
});

