import { createRequire } from "node:module"; import fs from "node:fs";
const req = createRequire(process.cwd() + "/"); const { chromium } = req("playwright");
const BASE = process.env.BASE, STATE = process.env.STATE || "idle", host = new URL(BASE).hostname;
const TOK = JSON.parse(fs.readFileSync("/tank/nxeon-build/promo-dev/tokens.json", "utf8"));
const OUT = "/tank/nxeon-build/promo-dev/shots"; fs.mkdirSync(OUT, { recursive: true });
const routes = (process.env.ROUTES || "partner").split(",").map((r) => r === "admin"
  ? ["admin", "/admin/partners?tab=partners", TOK.admin, "#promo-batch-game"]
  : r === "admin-detail" ? ["admin-detail", process.env.ADMIN_DETAIL, TOK.admin, null]
  : ["partner", "/dashboard/partner?tab=media", TOK.p1, null]);
const themes = (process.env.THEMES || "dark,light").split(","), widths = (process.env.WIDTHS || "1440,390").split(",").map(Number);
const b = await chromium.launch({ executablePath: process.env.CHROME, args: ["--disable-dev-shm-usage"] });
let bad = 0;
for (const [name, path, tok, anchor] of routes) for (const theme of themes) for (const w of widths) {
  if (name.startsWith("admin") && theme === "light") continue; // admin has no light mode
  const ctx = await b.newContext({ viewport: { width: w, height: 900 }, isMobile: w < 600 });
  await ctx.addCookies([{ name: "nxeon_session", value: tok, domain: host, path: "/" }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }, { name: "nxeon_cookie_consent", value: "necessary", domain: host, path: "/" }]);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); } catch {} }, theme);
  const p = await ctx.newPage(); const errs = [];
  p.on("pageerror", (e) => errs.push("pageerror: " + e.message));
  p.on("response", (r) => { if (r.status() >= 500) errs.push(`HTTP ${r.status()} ${r.url()}`); });
  const res = await p.goto(BASE + path, { waitUntil: "networkidle", timeout: 300000 });
  await p.waitForTimeout(1500);
  for (const btn of await p.getByRole("button", { name: /^(Got it|Dismiss|Close|Skip|Not now|Skip tour)$/ }).all()) await btn.click().catch(() => {});
  await p.addStyleTag({ content: "*{animation-duration:0s!important;animation-delay:0s!important;transition:none!important}" });
  const sel = anchor || "text=Make your own version";
  const el = await p.locator(sel).first().elementHandle().catch(() => null);
  if (el) await el.scrollIntoViewIfNeeded();
  await p.waitForTimeout(700);
  const sw = await p.evaluate(() => document.documentElement.scrollWidth);
  const txt = await p.evaluate(() => document.body.innerText);
  const ok = res?.status() === 200 && !errs.length && sw <= w && (name !== "partner" || /Make your own version/.test(txt));
  if (!ok) bad++;
  console.log(`${ok ? "OK  " : "FAIL"} ${STATE} ${name} ${theme} ${w} status=${res?.status()} sw=${sw}${errs.length ? " errs=" + errs.slice(0, 3).join(" | ") : ""}`);
  const file = `${OUT}/${STATE}-${name}-${theme}-${w}.png`;
  if (name === "partner") {
    // the card itself (full width, its own height)
    const card = p.locator("section.card", { hasText: "Make your own version" }).first();
    await card.screenshot({ path: file });
    await p.screenshot({ path: file.replace(".png", "-page.png"), fullPage: true });
  } else await p.screenshot({ path: file, fullPage: true });
  await ctx.close();
}
await b.close(); console.log(bad ? `${bad} FAILED` : "ALL OK");
