// Admin batch card + per-partner render list, 1440 + 390, dark + light (admin theme: localStorage nxeon.admin.theme).
import { createRequire } from "node:module"; import fs from "node:fs";
const req = createRequire(process.cwd() + "/"); const { chromium } = req("playwright");
const BASE = process.env.BASE, host = new URL(BASE).hostname;
const TOK = JSON.parse(fs.readFileSync("/tank/nxeon-build/promo-dev/tokens.json", "utf8"));
const OUT = ".promo-verify/out"; fs.mkdirSync(OUT, { recursive: true });
const routes = [["batch", "/admin/partners?tab=partners", "Render promo videos"], ["detail", process.env.ADMIN_DETAIL, "Generated promo videos"]];
const b = await chromium.launch({ executablePath: process.env.CHROME, args: ["--disable-dev-shm-usage"] });
let bad = 0;
for (const [name, path, heading] of routes) for (const theme of ["dark", "light"]) for (const w of [1440, 390]) {
  const ctx = await b.newContext({ viewport: { width: w, height: w >= 1000 ? 1300 : 900 }, isMobile: w < 600 });
  await ctx.addCookies([{ name: "nxeon_session", value: TOK.admin, domain: host, path: "/" }, { name: "nxeon_cookie_consent", value: "necessary", domain: host, path: "/" }]);
  await ctx.addInitScript((t) => { try { localStorage.setItem("nxeon.admin.theme", t); } catch {} }, theme);
  const p = await ctx.newPage(); const errs = [];
  p.on("pageerror", (e) => errs.push("pageerror: " + e.message));
  p.on("response", (r) => { if (r.status() >= 500) errs.push(`HTTP ${r.status()} ${r.url()}`); });
  const res = await p.goto(BASE + path, { waitUntil: "load", timeout: 300000 });
  const card = p.locator("div.card", { has: p.locator("p.section-label", { hasText: heading }) }).first();
  await card.waitFor({ timeout: 120000 });
  await p.addStyleTag({ content: "*{animation-duration:0s!important;transition:none!important}" });
  await card.scrollIntoViewIfNeeded(); await p.waitForTimeout(800);
  const sw = await p.evaluate(() => document.documentElement.scrollWidth);
  const ok = res?.status() === 200 && !errs.length && sw <= w;
  if (!ok) bad++;
  console.log(`${ok ? "OK  " : "FAIL"} admin-${name} ${theme} ${w} status=${res?.status()} sw=${sw}${errs.length ? " errs=" + errs.slice(0, 2).join(" | ") : ""}`);
  await card.screenshot({ path: `${OUT}/admin-${name}-${theme}-${w}.png`, timeout: 60000 });
  await ctx.close();
}
await b.close(); console.log(bad ? `${bad} FAILED` : "ALL OK");
EOF
